insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, explicit, visual_type, image_url, trivia, wikidata_qid, active) values
('ympstdsmvu', '1305-giotto-the-lamentation-of-christ', 'The Lamentation of Christ', 'Giotto', 1305, null, 'Proto-Renaissance', 'fresco', 'Scrovegni Chapel, Padua', 2, false, 'object', 'https://nambatu.github.io/circart-preview/art/ympstdsmvu.jpg', 'Enrico Scrovegni built the chapel partly to launder the family reputation: his father was a moneylender so notorious that Dante had parked him in the seventh circle of Hell a few years earlier. What Giotto delivered in exchange was a revolution in grief. Before this, mourners in painting stood around looking sad in a decorative way. Here they hunch, twist and howl, and the angels overhead are so distraught they appear to be tearing themselves apart. The two figures with their backs to us, blocking our view, were unheard of.', null, true),
('fygc6kywxe', '1311-duccio-di-buoninsegna-maesta', 'Maestà', 'Duccio di Buoninsegna', 1311, null, 'Sienese School', 'tempera on panel', 'Museo dell''Opera del Duomo, Siena', 3, false, 'object', 'https://nambatu.github.io/circart-preview/art/fygc6kywxe.jpg', 'Delivered to Siena cathedral in a procession with trumpets, candles and every shop in the city closed for the day, which tells you how a medieval town felt about a new altarpiece. Its later career was less dignified: in 1771 the cathedral decided it was old-fashioned, sawed it into pieces and scattered the panels. Bits are now in London, Washington and New York, and the reassembled front is a jigsaw with missing tiles.', 'Q667202', true),
('srapcupy3s', '1339-ambrogio-lorenzetti-the-allegory-of-good-and-bad-gov', 'The Allegory of Good and Bad Government', 'Ambrogio Lorenzetti', 1339, null, 'Sienese School', 'fresco', 'Palazzo Pubblico, Siena', 3, false, 'object', 'https://nambatu.github.io/circart-preview/art/srapcupy3s.jpg', 'Painted around the walls of the room where Siena''s nine ruling magistrates actually sat, so they had to work inside a visual argument about their own conduct. Good Government shows a city where people dance in the street and merchants trade unmolested. Bad Government, on the opposite wall, has a demon on the throne and buildings falling down, and it is the more damaged of the two, which is either an accident of humidity or the single best piece of historical irony in Italian fresco.', 'Q2401235', true),
('zcuzgngaaa', '1416-limbourg-brothers-tres-riches-heures-february', 'Très Riches Heures: February', 'Limbourg Brothers', 1416, 'calendar pages painted c. 1412-16; the manuscript was left unfinished and later folios, including Hell, are by Jean Colombe from 1485', 'International Gothic', 'illuminated manuscript', 'Musée Condé, Chantilly', 2, false, 'object', 'https://nambatu.github.io/circart-preview/art/zcuzgngaaa.jpg', 'The earliest known snow scene in Western art, and the Limbourgs had to invent most of it: a February page in a book of hours conventionally showed somebody warming by a fire or chopping twigs in a bare landscape, and they gave almost the whole page to what is happening outside instead, with a woodcutter, a donkey on the road, a dovecote, sheep, and beehives under snow. Inside the open-fronted farmhouse, two peasants have hitched their tunics up to warm their legs and are exposing themselves entirely, while the woman beside them decorously warms only her ankles. The blue is ground lapis lazuli, more expensive by weight than gold. All three brothers died in 1416, probably of plague, in the same year as their patron, none of them yet thirty, and the manuscript sat unfinished for seventy years until Jean Colombe was hired to complete it.', 'Q16941223', true),
('japmnwuwdw', '1425-masaccio-the-tribute-money', 'The Tribute Money', 'Masaccio', 1425, null, 'Early Renaissance', 'fresco', 'Brancacci Chapel, Florence', 2, false, 'object', 'https://nambatu.github.io/circart-preview/art/japmnwuwdw.jpg', 'Masaccio put the vanishing point of the entire perspective scheme directly at the head of Christ, so the architecture of the world converges on him whether you notice or not. He was 23 and would be dead at 26. Vasari claimed every serious Florentine painter of the next century came to this chapel to study, and Michelangelo was among them, until a fellow student broke his nose in an argument on the scaffolding.', null, true),
('aa4sbjjjav', '1427-masaccio-holy-trinity', 'Holy Trinity', 'Masaccio', 1427, null, 'Early Renaissance', 'fresco', 'Santa Maria Novella, Florence', 3, false, 'object', 'https://nambatu.github.io/circart-preview/art/aa4sbjjjav.jpg', 'The painted barrel vault was so convincing that contemporaries described walking up to the wall to check whether the chapel was real. It is the first surviving painting built on a mathematically consistent one-point perspective scheme, executed just a few years after Brunelleschi worked out the system. At the bottom, a skeleton on a tomb carries an inscription telling the viewer that what you are, I once was, and what I am, you will be. Renaissance painting begins with a memento mori and a magic trick in the same picture.', 'Q977200', true),
('xpwajjqect', '1432-jan-van-eyck-the-ghent-altarpiece', 'The Ghent Altarpiece', 'Jan van Eyck', 1432, null, 'Northern Renaissance', 'oil on panel', 'Saint Bavo Cathedral, Ghent', 2, false, 'object', 'https://nambatu.github.io/circart-preview/art/xpwajjqect.jpg', 'The most frequently stolen artwork in history, by some distance. It has been burned at, dismembered, ransomed by Napoleon, handed over as a First World War reparation, hidden in an Austrian salt mine by the Nazis and rescued by the Monuments Men. One panel taken in 1934 has never been found and is still represented by a copy. Recent cleaning also removed centuries of overpaint from the Mystic Lamb, revealing an unnervingly humanoid face with forward-set eyes that briefly went viral.', 'Q734834', true),
('54qghsqhme', '1434-jan-van-eyck-the-arnolfini-portrait', 'The Arnolfini Portrait', 'Jan van Eyck', 1434, null, 'Northern Renaissance', 'oil on oak', 'National Gallery, London', 1, false, 'object', 'https://nambatu.github.io/circart-preview/art/54qghsqhme.jpg', 'High on the back wall, in gold, in the elaborate notarial script used for legal documents, Van Eyck wrote Johannes de eyck fuit hic 1434, which translates as Jan van Eyck was here. It is toilet-wall graffiti executed in the handwriting of a contract, on one of the most technically accomplished paintings in Europe, and it is positioned directly above a convex mirror barely five centimetres across in which he painted the entire room from behind, two extra figures standing in the doorway roughly where you are, and ten separate scenes of the Passion around the frame. Two corrections while you are looking: the woman is not pregnant, she is holding up an expensive amount of cloth in the fashion of the day, and the theory that the picture records a wedding is now widely doubted. What it records may simply be that he was there.', 'Q220859', true),
('theu3chqwk', '1438-paolo-uccello-the-battle-of-san-romano', 'The Battle of San Romano', 'Paolo Uccello', 1438, 'c. 1435-1440', 'Early Renaissance', 'tempera on panel', 'National Gallery, London', 3, false, 'object', 'https://nambatu.github.io/circart-preview/art/theu3chqwk.jpg', 'Uccello was so consumed by perspective that his wife reportedly complained he stayed up all night muttering about it. Look at the ground: the broken lances have been arranged into a neat receding grid, because a battlefield was less interesting to him than an opportunity. The three panels were made for the Medici, and Lorenzo the Magnificent later wanted them so badly that he had them removed from another family''s house, arguably by force.', 'Q18564234', true),
('6jh6uyrfkm', '1440-donatello-david', 'David', 'Donatello', 1440, null, 'Early Renaissance', 'bronze', 'Bargello, Florence', 2, false, 'public_sculpture', 'https://nambatu.github.io/circart-preview/art/6jh6uyrfkm.jpg', 'The first free-standing nude statue cast since antiquity, and it was not made for a church. It stood in the private courtyard of the Medici palace, where a naked adolescent boy in nothing but boots and a hat, standing on the severed head of Goliath, was presented as a civic virtue. Nobody has ever quite explained the hat. Vasari praised its naturalism so warmly that he claimed it had been cast from a living body.', 'Q735085', true),
('tw7y877p67', '1443-fra-angelico-the-annunciation', 'The Annunciation', 'Fra Angelico', 1443, 'c. 1440-1445', 'Early Renaissance', 'fresco', 'Convent of San Marco, Florence', 2, false, 'object', 'https://nambatu.github.io/circart-preview/art/tw7y877p67.jpg', 'Painted at the top of the stairs in a Dominican convent, so a monk climbing to his cell met it every single day. Fra Angelico was himself a friar, and the fresco has no gold, no crowd and no spectacle, just a bare loggia and two figures leaning slightly toward each other. An inscription along the base reminds the reader to say a Hail Mary when passing. It is one of the few Renaissance masterpieces that was designed to be walked past rather than looked at.', 'Q2378534', true),
('zbzwd4ba6b', '1455-rogier-van-der-weyden-the-descent-from-the-cross', 'The Descent from the Cross', 'Rogier van der Weyden', 1455, 'c. 1435', 'Northern Renaissance', 'oil on panel', 'Museo del Prado, Madrid', 3, false, 'object', 'https://nambatu.github.io/circart-preview/art/zbzwd4ba6b.jpg', 'The body of Christ and the collapsing body of the Virgin below him form two almost identical curves, a visual rhyme that lets you feel her grief structurally before you read it emotionally. Van der Weyden crammed ten life-size figures into a shallow gold box, like a carved altarpiece rather than a window. Philip II of Spain wanted it so much that he sent a copy to the guild that owned it, and took the original.', 'Q568847', true),
('dn6bbz5592', '1460-piero-della-francesca-the-flagellation-of-christ', 'The Flagellation of Christ', 'Piero della Francesca', 1460, 'c. 1455-1460', 'Early Renaissance', 'tempera on panel', 'Galleria Nazionale delle Marche, Urbino', 3, false, 'object', 'https://nambatu.github.io/circart-preview/art/dn6bbz5592.jpg', 'Kenneth Clark called it the greatest small painting in the world, which is a strong claim for a panel under 60 centimetres wide that nobody can explain. Christ is being scourged in the far background under perfect perspective, while three unidentified men stand chatting in the foreground, dominating the composition. Theories about who they are include a lament for the fall of Constantinople and a coded reference to a political murder in Urbino. There is no consensus and probably never will be.', 'Q1212920', true),
('prccd36zca', '1474-piero-della-francesca-montefeltro-sforza-diptych', 'Diptych of Federico da Montefeltro and Battista Sforza', 'Piero della Francesca', 1474, 'dated 1473-75 by most scholarship; some sources give 1465-72', 'Early Renaissance', 'oil and tempera on panel', 'Uffizi, Florence', 2, false, 'object', 'https://nambatu.github.io/circart-preview/art/prccd36zca.jpg', 'The Duke is shown in strict left profile because he had lost his right eye and part of the bridge of his nose in a tournament. He is said to have had the surviving bridge surgically cut back afterwards to widen his field of vision on the remaining side, which is either brilliant or horrifying depending on your view of fifteenth-century surgery. The reverse sides show the couple riding in triumphal carts, so the object was meant to be handled, not hung.', 'Q113549604', true),
('ppbkbcr8kb', '1478-sandro-botticelli-primavera', 'Primavera', 'Sandro Botticelli', 1478, 'c. 1477-1482', 'Early Renaissance', 'tempera on panel', 'Uffizi, Florence', 1, false, 'object', 'https://nambatu.github.io/circart-preview/art/ppbkbcr8kb.jpg', 'Botanists have identified around 500 plant species in the meadow, the great majority of which genuinely flower in Tuscany between March and May. The painting is a masterpiece and also a field guide. Its meaning is contested to a comic degree: it has been read as Neoplatonic philosophy, a marriage gift, a medical allegory and a coded Medici family tree. Vasari saw it in a Medici villa in the 1550s and it then dropped out of critical view for roughly three centuries.', 'Q549847', true),
('qg73zs7sxa', '1480-andrea-mantegna-the-lamentation-of-christ', 'The Lamentation of Christ', 'Andrea Mantegna', 1480, null, 'Early Renaissance', 'tempera on canvas', 'Pinacoteca di Brera, Milan', 2, false, 'object', 'https://nambatu.github.io/circart-preview/art/qg73zs7sxa.jpg', 'Mantegna aimed the soles of Christ''s feet directly at the viewer, which is the single most aggressive piece of foreshortening in Renaissance painting. He also cheated: the feet are painted smaller than true perspective would make them, because true perspective would have produced a picture that was mostly feet. It was found in his studio after his death, unsold, and may have been intended for his own tomb chapel.', 'Q546297', true),
('ey272y9qy3', '1485-sandro-botticelli-the-birth-of-venus', 'The Birth of Venus', 'Sandro Botticelli', 1485, null, 'Early Renaissance', 'tempera on canvas', 'Uffizi, Florence', 1, false, 'object', 'https://nambatu.github.io/circart-preview/art/ey272y9qy3.jpg', 'Painted on canvas rather than wooden panel, which was cheap and unusual, suggesting it hung somewhere informal like a country villa rather than a palace. It is the first large-scale image of a nude goddess in Western art since antiquity, produced in a city that would, within a decade, be throwing luxury objects onto Savonarola''s bonfires. Botticelli reportedly became a follower of Savonarola himself, and his late work turns grim and flat, as if he were arguing with this painting.', 'Q151047', true),
('q2shkr92nx', '1490-domenico-ghirlandaio-an-old-man-and-his-grandson', 'An Old Man and His Grandson', 'Domenico Ghirlandaio', 1490, null, 'Early Renaissance', 'tempera on panel', 'Louvre, Paris', 3, false, 'object', 'https://nambatu.github.io/circart-preview/art/q2shkr92nx.jpg', 'The old man''s nose is disfigured by rhinophyma, a condition Ghirlandaio painted with clinical exactness at a moment when portraiture existed largely to flatter. What makes the picture is that the child is not recoiling. He has one hand on the man''s chest and is looking straight up at his face. A surviving drawing shows Ghirlandaio studied the man after death, which means this warm domestic scene was assembled around a corpse study.', 'Q23915', true),
('8n9v75tsyg', '1498-leonardo-da-vinci-the-last-supper', 'The Last Supper', 'Leonardo da Vinci', 1498, 'begun 1495', 'High Renaissance', 'tempera and oil on plaster', 'Santa Maria delle Grazie, Milan', 1, false, 'object', 'https://nambatu.github.io/circart-preview/art/8n9v75tsyg.jpg', 'Leonardo could not bear the speed of true fresco, which requires you to finish a section before the plaster dries, so he invented his own method using oil and tempera on dry wall. It began flaking within twenty years and was described as a ruin within fifty. The refectory has since been bombed in 1943 and had a door cut through Christ''s feet in 1652. Almost everything you see has been restored. The gestures are the point: Leonardo choreographed the exact moment after the accusation lands.', 'Q128910', true),
('9486uch8kk', '1500-albrecht-durer-self-portrait-at-twenty-eight', 'Self-Portrait at Twenty-Eight', 'Albrecht Dürer', 1500, null, 'Northern Renaissance', 'oil on lime panel', 'Alte Pinakothek, Munich', 2, false, 'object', 'https://nambatu.github.io/circart-preview/art/9486uch8kk.jpg', 'Dürer painted himself frontal and symmetrical, with his hand raised in a gesture of blessing, in the pose reserved almost exclusively for images of Christ. This was somewhere between a theological argument about creativity and outright blasphemy, and he did it at 28. He was also a genuine businessman who understood printing as mass media, travelled to Venice to complain about people pirating his engravings, and made himself the first artist in Europe with an international brand.', null, true),
('n9sjdrctfr', '1500-hieronymus-bosch-the-garden-of-earthly-delights', 'The Garden of Earthly Delights', 'Hieronymus Bosch', 1500, 'c. 1490-1510', 'Northern Renaissance', 'oil on oak', 'Museo del Prado, Madrid', 1, false, 'object', 'https://nambatu.github.io/circart-preview/art/n9sjdrctfr.jpg', 'In 2014 a Texas student transcribed the musical notation painted across a damned figure''s backside in the hell panel and recorded it, and the resulting piece of five-hundred-year-old butt music went comprehensively viral. That is the internet''s contribution. The scholarly contribution is that we still cannot agree whether the central panel is a warning against sin or a depiction of an innocent paradise that never fell, and Bosch left no writings whatsoever to settle it.', 'Q321303', true),
('qfss9crjpx', '1503-leonardo-da-vinci-mona-lisa', 'Mona Lisa', 'Leonardo da Vinci', 1503, 'c. 1503-1506', 'High Renaissance', 'oil on poplar', 'Louvre, Paris', 1, false, 'object', 'https://nambatu.github.io/circart-preview/art/qfss9crjpx.jpg', 'It was a moderately admired picture until 1911, when a Louvre handyman named Vincenzo Peruggia walked out with it under his coat. The empty wall drew larger crowds than the painting ever had, Picasso was questioned as a suspect, and by the time it came back two years later it was the most famous object in the world. Fame was retroactive. Leonardo also never delivered it to whoever commissioned it, carrying it around for over a decade instead.', 'Q12418', true),
('ygpwfg75ft', '1504-michelangelo-david', 'David', 'Michelangelo', 1504, null, 'High Renaissance', 'marble', 'Galleria dell''Accademia, Florence', 1, false, 'public_sculpture', 'https://nambatu.github.io/circart-preview/art/ygpwfg75ft.jpg', 'Carved from a block of marble that two earlier sculptors had started and abandoned as ruined, which is why the figure is unusually shallow front to back. Michelangelo was 26. A committee including Botticelli and Leonardo argued for weeks about where to put it, and when it was moved, people threw stones at it. The proportions are deliberately wrong: the head and right hand are oversized, because it was designed to be seen from far below on a cathedral buttress.', 'Q179900', true),
('9ergdvf6gt', '1505-giorgione-the-tempest', 'The Tempest', 'Giorgione', 1505, 'c. 1506-1508', 'Venetian Renaissance', 'oil on canvas', 'Gallerie dell''Accademia, Venice', 3, false, 'object', 'https://nambatu.github.io/circart-preview/art/9ergdvf6gt.jpg', 'Nobody has ever established what is happening. X-rays show Giorgione originally painted a second nude woman bathing where the soldier now stands, meaning he changed the entire subject partway through, which strongly suggests the subject was not the point. It may be the first European painting where landscape and mood outrank narrative. Giorgione died of plague around 35, left barely six securely attributed paintings, and remains one of art history''s most consequential near-blanks.', 'Q930137', true),
('9wkj2hb38d', '1511-raphael-the-school-of-athens', 'The School of Athens', 'Raphael', 1511, 'begun 1509', 'High Renaissance', 'fresco', 'Vatican Museums, Vatican City', 1, false, 'object', 'https://nambatu.github.io/circart-preview/art/9wkj2hb38d.jpg', 'Raphael painted the brooding figure sprawled on the steps only after sneaking a look at the Sistine ceiling in progress next door, and it is a portrait of Michelangelo, inserted late into wet plaster. Plato has Leonardo''s face. Raphael put himself in the crowd at the right, looking out. The whole thing is a room full of philosophers who could never have met, arranged so that Plato points up at ideals and Aristotle levels his hand at the world.', 'Q186953', true),
('hygyp8w3q2', '1512-michelangelo-the-creation-of-adam', 'The Creation of Adam', 'Michelangelo', 1512, null, 'High Renaissance', 'fresco', 'Sistine Chapel, Vatican City', 1, false, 'object', 'https://nambatu.github.io/circart-preview/art/hygyp8w3q2.jpg', 'Michelangelo considered himself a sculptor, took the ceiling commission under protest, and wrote a bitter comic poem about the work in which he describes his beard pointing at heaven and his brain collapsing into a casket. He did not paint lying down, as the legend claims, but standing on scaffolding with his head bent back. A physician suggested in 1990 that the shape framing God is an anatomically accurate cross-section of the human brain, which is either profound or pareidolia.', 'Q500242', true),
('gfesjywmdh', '1513-albrecht-durer-knight-death-and-the-devil', 'Knight, Death and the Devil', 'Albrecht Dürer', 1513, null, 'Northern Renaissance', 'engraving', 'various collections', 3, false, 'object', 'https://nambatu.github.io/circart-preview/art/gfesjywmdh.jpg', 'Dürer sold engravings like this one at markets and fairs across Europe, and prints, not paintings, are what made him rich. The knight rides past Death holding an hourglass and a pig-snouted devil without acknowledging either, which is the entire moral. Nietzsche loved it. So, unfortunately, did the Nazis, who adopted the image as a symbol of steadfast German will, an appropriation the print has never fully shaken off.', null, true),
('s5k69s3cz7', '1514-albrecht-durer-melencolia-i', 'Melencolia I', 'Albrecht Dürer', 1514, null, 'Northern Renaissance', 'engraving', 'various collections', 3, false, 'object', 'https://nambatu.github.io/circart-preview/art/s5k69s3cz7.jpg', 'The magic square in the upper right has every row, column and diagonal summing to 34, and the two middle cells of the bottom row read 15 and 14, which is the year. The winged figure sits surrounded by the tools of geometry and does nothing at all. Panofsky read it as a portrait of the creative mind stalled by its own standards, which is why it hangs in more academic offices than any other Renaissance print.', null, true),
('bgz4weuw6k', '1515-matthias-grunewald-the-isenheim-altarpiece', 'The Isenheim Altarpiece', 'Matthias Grünewald', 1515, 'c. 1512-1516', 'Northern Renaissance', 'oil on panel', 'Musée Unterlinden, Colmar', 2, false, 'object', 'https://nambatu.github.io/circart-preview/art/bgz4weuw6k.jpg', 'Painted for a hospital run by monks who treated ergotism, a disease caused by fungus-infected rye that produced convulsions, gangrene and the sensation of burning alive. Grünewald gave the crucified Christ the same skin lesions the patients had, so the dying could look at a god with their disease. The altarpiece also opens: behind the horror is a resurrection panel in colours so bright they look artificially lit. It was designed as a treatment.', null, true),
('srmmpmmznw', '1520-raphael-the-transfiguration', 'The Transfiguration', 'Raphael', 1520, null, 'High Renaissance', 'tempera on wood', 'Vatican Museums, Vatican City', 3, false, 'object', 'https://nambatu.github.io/circart-preview/art/srmmpmmznw.jpg', 'Left unfinished when Raphael died at 37, on his birthday, after what contemporaries described as a fever following an energetic night. The painting was placed at the head of his funeral bier. It is also two paintings uneasily bolted together: serene levitation above, a chaotic scene of a possessed boy below. Critics complained about the incoherence for centuries until the Romantics decided it was the point.', 'Q2344437', true),
('54czvugjdd', '1524-parmigianino-self-portrait-in-a-convex-mirror', 'Self-Portrait in a Convex Mirror', 'Parmigianino', 1524, null, 'Mannerism', 'oil on convex panel', 'Kunsthistorisches Museum, Vienna', 3, false, 'object', 'https://nambatu.github.io/circart-preview/art/54czvugjdd.jpg', 'Parmigianino had a curved wooden panel specially made so that the distortion of the barber''s mirror he was copying would be physically reproduced in the object itself. His hand balloons toward you, his face stays small and calm. He was about 21. Vasari reports that he later abandoned painting for alchemy, grew a wild beard and died at 37, which may be gossip but is the kind of gossip a painting like this invites.', 'Q699319', true),
('xs8xx9jzr9', '1533-hans-holbein-the-younger-the-ambassadors', 'The Ambassadors', 'Hans Holbein the Younger', 1533, null, 'Northern Renaissance', 'oil on oak', 'National Gallery, London', 2, false, 'object', 'https://nambatu.github.io/circart-preview/art/xs8xx9jzr9.jpg', 'The grey smear across the floor resolves into a perfect human skull if you stand at the lower right edge of the frame, which is exactly where you end up if the painting hangs beside a staircase. Everything in the picture is a status object: globes, sundials, a lute, a Lutheran hymn book. One lute string is broken. It is a portrait of two young men at the height of their powers with death drawn diagonally across the carpet.', 'Q1212937', true),
('272qrhex7e', '1538-titian-venus-of-urbino', 'Venus of Urbino', 'Titian', 1538, null, 'Venetian Renaissance', 'oil on canvas', 'Uffizi, Florence', 2, true, 'object', 'https://nambatu.github.io/circart-preview/art/272qrhex7e.jpg', 'Mark Twain devoted a passage of A Tramp Abroad to calling it the foulest picture the world possesses, while conceding he had gone back for a second look. Modern scholarship is fairly confident it was a marriage painting, kept in a private chamber, and that the sleeping dog signals fidelity while the maids in the background rummage in a wedding chest. Manet''s Olympia is a direct, hostile quotation of it three centuries later.', 'Q727875', true),
('6ua3w7b9ry', '1545-bronzino-venus-cupid-folly-and-time', 'Venus, Cupid, Folly and Time', 'Bronzino', 1545, 'c. 1545', 'Mannerism', 'oil on panel', 'National Gallery, London', 3, false, 'object', 'https://nambatu.github.io/circart-preview/art/6ua3w7b9ry.jpg', 'A diplomatic gift from Cosimo de'' Medici to the King of France, packed with allegory so dense that no two scholars agree on it. Cupid is fondling his own mother. The smiling child scattering rose petals has the hindquarters of an animal. The screaming figure on the left has been diagnosed as representing syphilis, then jealousy, then despair. Victorian owners had parts of it painted over, and the overpainting was only removed in the 1950s.', 'Q1430990', true),
('zua8r2a3m6', '1559-pieter-bruegel-the-elder-netherlandish-proverbs', 'Netherlandish Proverbs', 'Pieter Bruegel the Elder', 1559, null, 'Northern Renaissance', 'oil on oak', 'Gemäldegalerie, Berlin', 2, false, 'object', 'https://nambatu.github.io/circart-preview/art/zua8r2a3m6.jpg', 'Around 112 identifiable proverbs are being acted out at once, including banging your head against a brick wall, armed to the teeth, and casting roses before swine. A man is quite literally shitting on the world. Bruegel''s audience would have read it the way we read a dense meme, catching maybe forty on a first pass. The cumulative message is bleak: every proverb depicted is about human folly, and none about wisdom.', null, true),
('dbwmt65c5f', '1563-pieter-bruegel-the-elder-the-tower-of-babel', 'The Tower of Babel', 'Pieter Bruegel the Elder', 1563, null, 'Northern Renaissance', 'oil on panel', 'Kunsthistorisches Museum, Vienna', 1, false, 'object', 'https://nambatu.github.io/circart-preview/art/dbwmt65c5f.jpg', 'Bruegel had been to Rome and modelled the tower on the Colosseum, so the great monument of human pride is built in the shape of a ruin that was already ancient. The structure is architecturally doomed and he knew it: the arches are visibly misaligned, and the whole thing tilts. Antwerp at the time was a boom city stuffed with dozens of languages and hectic new money, which is almost certainly the real subject.', null, true),
('y6khez2m9d', '1565-pieter-bruegel-the-elder-hunters-in-the-snow', 'Hunters in the Snow', 'Pieter Bruegel the Elder', 1565, null, 'Northern Renaissance', 'oil on panel', 'Kunsthistorisches Museum, Vienna', 1, false, 'object', 'https://nambatu.github.io/circart-preview/art/y6khez2m9d.jpg', 'Painted during the Little Ice Age, the year after one of the harshest winters on European record, when the canals froze solid and people genuinely skated to work. Bruegel invented the snow landscape as a subject more or less single-handedly. The hunters are returning with one thin fox between them, the dogs have their tails down, and the sky is the colour of dishwater. It is a beloved picture about a failed hunt.', null, true),
('qvnaamgxnw', '1573-paolo-veronese-the-feast-in-the-house-of-levi', 'The Feast in the House of Levi', 'Paolo Veronese', 1573, null, 'Venetian Renaissance', 'oil on canvas', 'Gallerie dell''Accademia, Venice', 3, false, 'object', 'https://nambatu.github.io/circart-preview/art/qvnaamgxnw.jpg', 'Painted as a Last Supper, until the Inquisition summoned Veronese to explain the dwarfs, the dogs, the German soldiers and the man with a nosebleed. His defence, essentially that painters take the same liberties as poets and madmen, did not persuade them. Ordered to fix it at his own expense within three months, he changed the title instead, and the Inquisition let it go. Possibly the most efficient act of artistic self-defence on record.', 'Q951105', true),
('9swk642d69', '1586-el-greco-the-burial-of-the-count-of-orgaz', 'The Burial of the Count of Orgaz', 'El Greco', 1586, null, 'Mannerism', 'oil on canvas', 'Santo Tomé, Toledo', 2, false, 'object', 'https://nambatu.github.io/circart-preview/art/9swk642d69.jpg', 'Still hangs in the church it was painted for, directly above the tomb it depicts, which is roughly a 1% survival scenario for a sixteenth-century commission. The lower half is a sober row of Toledo notables in black; the upper half detonates into elongated, weightless figures in acid colours. El Greco painted his own son as the boy at the front and put the date of the boy''s birth on his handkerchief.', 'Q94802', true),
('vauvyrmb5s', '1591-giuseppe-arcimboldo-vertumnus', 'Vertumnus', 'Giuseppe Arcimboldo', 1591, null, 'Mannerism', 'oil on panel', 'Skokloster Castle, Sweden', 2, false, 'object', 'https://nambatu.github.io/circart-preview/art/vauvyrmb5s.jpg', 'A portrait of the Holy Roman Emperor Rudolf II built entirely out of fruit and vegetables, and by all accounts he was thrilled with it. Rudolf was a spectacularly strange monarch who collected narwhal horns, employed astrologers and alchemists, and largely ignored governing. Arcimboldo was his court portraitist for years. The paintings were dismissed as jokes until the Surrealists rediscovered them in the twentieth century and claimed him as an ancestor.', 'Q16333797', true),
('xkgxebc2gz', '1594-tintoretto-the-last-supper', 'The Last Supper', 'Tintoretto', 1594, null, 'Mannerism', 'oil on canvas', 'San Giorgio Maggiore, Venice', 3, false, 'object', 'https://nambatu.github.io/circart-preview/art/xkgxebc2gz.jpg', 'Tintoretto ran the table diagonally into darkness instead of parallel to the picture plane, which was heresy against a century of convention. The upper half swarms with angels made of smoke from the oil lamp, and the servants clearing plates get as much attention as the apostles. He painted it in the last year of his life. He also famously won commissions by installing finished work overnight, unasked, then daring the client to remove it.', null, true),
('af2xq6czx7', '1599-caravaggio-judith-beheading-holofernes', 'Judith Beheading Holofernes', 'Caravaggio', 1599, 'c. 1598-1599', 'Baroque', 'oil on canvas', 'Palazzo Barberini, Rome', 2, true, 'object', 'https://nambatu.github.io/circart-preview/art/af2xq6czx7.jpg', 'Caravaggio used a well-known Roman courtesan as his model for Judith, and painted the arterial spray with a precision that suggests he had watched a beheading, which in papal Rome was a public event. Judith''s expression is the strangest thing in it: not triumph, not horror, but the mild distaste of someone doing an unpleasant chore. Artemisia Gentileschi would answer this painting thirteen years later with a version where Judith puts her back into it.', 'Q2470123', true),
('vzqf4tt92j', '1600-caravaggio-the-calling-of-saint-matthew', 'The Calling of Saint Matthew', 'Caravaggio', 1600, null, 'Baroque', 'oil on canvas', 'San Luigi dei Francesi, Rome', 2, false, 'object', 'https://nambatu.github.io/circart-preview/art/vzqf4tt92j.jpg', 'The tax collectors wear the fashionable Roman dress of 1600, so the miracle appears to be happening in a contemporary bar to people the congregation might have met. Art historians have argued for decades over which figure is actually Matthew: the bearded man pointing at himself, or the young man staring down at the coins, in which case the pointing gesture means who, him? The light comes from a window that does not exist in the painted room but does exist in the chapel.', 'Q969377', true),
('89f3h7p5z8', '1601-caravaggio-supper-at-emmaus', 'Supper at Emmaus', 'Caravaggio', 1601, null, 'Baroque', 'oil on canvas', 'National Gallery, London', 3, false, 'object', 'https://nambatu.github.io/circart-preview/art/89f3h7p5z8.jpg', 'The fruit basket is teetering over the edge of the table into your space, and the fruit is visibly going off, wormholes and all. Caravaggio painted a beardless Christ, which infuriated critics who wanted the standard iconography, and gave the apostle on the right a torn sleeve. He was, by then, a celebrated painter who lived like a thug, carried a sword without a permit and generated a police file that survives in unusual detail.', 'Q318947', true),
('74f8g87m8z', '1610-caravaggio-david-with-the-head-of-goliath', 'David with the Head of Goliath', 'Caravaggio', 1610, null, 'Baroque', 'oil on canvas', 'Galleria Borghese, Rome', 3, false, 'object', 'https://nambatu.github.io/circart-preview/art/74f8g87m8z.jpg', 'The severed head is a self-portrait. Caravaggio had killed a man in 1606 and was under a papal death sentence, and this painting was almost certainly sent to Rome as a plea for pardon, offering up his own head in paint. He died the same year, aged 38, on a beach, in circumstances still argued over. The pardon, by some accounts, had already been granted and he never learned of it.', 'Q2721037', true),
('3asce258u5', '1612-artemisia-gentileschi-judith-slaying-holofernes', 'Judith Slaying Holofernes', 'Artemisia Gentileschi', 1612, 'c. 1612-1613', 'Baroque', 'oil on canvas', 'Museo di Capodimonte, Naples', 2, true, 'object', 'https://nambatu.github.io/circart-preview/art/3asce258u5.jpg', 'Gentileschi painted this in the years surrounding the trial of Agostino Tassi, who had raped her, and at which she was tortured with thumbscrews to verify her testimony. He was convicted and never served the sentence. Reading the painting as pure revenge is now considered reductive, but the mechanics are undeniable: unlike Caravaggio''s Judith, hers has leverage, braced arms and a maid actively pinning the man down. It was owned by the Medici and kept out of public view for a long time.', 'Q2247406', true),
('tjpyrf2fqe', '1618-peter-paul-rubens-the-rape-of-the-daughters-of-leu', 'The Rape of the Daughters of Leucippus', 'Peter Paul Rubens', 1618, null, 'Baroque', 'oil on canvas', 'Alte Pinakothek, Munich', 3, false, 'object', 'https://nambatu.github.io/circart-preview/art/tjpyrf2fqe.jpg', 'Rubens ran what was effectively a painting factory with dozens of assistants, and charged clients according to how much of the canvas he had touched personally, an itemised pricing model that survives in his correspondence. He was also a working diplomat, fluent in several languages, knighted by two kings. The composition here is a rotating pinwheel of bodies and horses that has no stable ground, which is the entire Baroque programme in one canvas.', 'Q644936', true),
('vh8b5s3hwx', '1623-gian-lorenzo-bernini-apollo-and-daphne', 'Apollo and Daphne', 'Gian Lorenzo Bernini', 1623, 'begun 1622', 'Baroque', 'marble', 'Galleria Borghese, Rome', 2, false, 'public_sculpture', 'https://nambatu.github.io/circart-preview/art/vh8b5s3hwx.jpg', 'Bernini was 24 and carved the laurel leaves so thin that they are translucent and ring faintly when tapped. Daphne is caught in the single second between woman and tree, with bark crawling up her thigh and her fingers already sprouting. A cardinal, worried about a life-size nude in a religious household, had a moralising Latin couplet attached to the base explaining that those who chase fleeting pleasures end up with leaves and berries.', 'Q945850', true),
('sne9z8b57s', '1624-frans-hals-the-laughing-cavalier', 'The Laughing Cavalier', 'Frans Hals', 1624, null, 'Dutch Golden Age', 'oil on canvas', 'Wallace Collection, London', 2, false, 'object', 'https://nambatu.github.io/circart-preview/art/sne9z8b57s.jpg', 'He is not laughing and he is not a cavalier. A Victorian exhibition catalogue invented the name in the 1870s and it stuck so thoroughly that the real title is forgotten. What Hals could actually do is visible in the sleeve: the embroidery is a blizzard of loose, fast strokes that resolve at a distance and dissolve up close. He died in poverty in an almshouse, and the Impressionists rediscovered him two centuries later.', 'Q965124', true),
('e39nggyfck', '1632-rembrandt-the-anatomy-lesson-of-dr-nicolae', 'The Anatomy Lesson of Dr Nicolaes Tulp', 'Rembrandt', 1632, null, 'Dutch Golden Age', 'oil on canvas', 'Mauritshuis, The Hague', 2, false, 'object', 'https://nambatu.github.io/circart-preview/art/e39nggyfck.jpg', 'Public dissections were ticketed events held in purpose-built theatres, with music, and this one used the body of an executed armed robber named Aris Kindt. Rembrandt was 26 and had just arrived in Amsterdam. He broke the group-portrait convention by refusing to line the surgeons up, instead clustering them into a pile of craning necks. The dissected forearm is anatomically wrong, and nobody has convincingly explained why.', 'Q661378', true),
('yqb28t9egh', '1635-francisco-de-zurbaran-agnus-dei', 'Agnus Dei', 'Francisco de Zurbarán', 1635, 'c. 1635-1640', 'Baroque', 'oil on canvas', 'Museo del Prado, Madrid', 3, false, 'object', 'https://nambatu.github.io/circart-preview/art/yqb28t9egh.jpg', 'A bound lamb on a bare stone slab against a black void, painted with nothing else in the frame. Zurbarán made several versions and they are among the strangest religious objects of the century: technically a still life, functionally an altarpiece, emotionally a photograph of an animal about to be killed. He spent his career supplying Spanish monasteries and shipping paintings by the crate to colonial South America, and died poor after tastes shifted toward Murillo.', null, true),
('jkxtxvza64', '1638-nicolas-poussin-et-in-arcadia-ego', 'Et in Arcadia Ego', 'Nicolas Poussin', 1638, null, 'Baroque Classicism', 'oil on canvas', 'Louvre, Paris', 3, false, 'object', 'https://nambatu.github.io/circart-preview/art/jkxtxvza64.jpg', 'Shepherds in a perfect pastoral landscape crouch to read an inscription on a tomb, and the Latin means roughly that even in Arcadia, I am here, the I being death. Poussin worked in Rome, painted for a small circle of intellectual collectors, and reportedly built little wax models in a box so he could arrange his figures like a stage set. The painting later became a fixture of conspiracy literature about secret bloodlines, which he would have found appalling.', 'Q1140358', true),
('kaxb6jvdbz', '1642-rembrandt-the-night-watch', 'The Night Watch', 'Rembrandt', 1642, null, 'Dutch Golden Age', 'oil on canvas', 'Rijksmuseum, Amsterdam', 1, false, 'object', 'https://nambatu.github.io/circart-preview/art/kaxb6jvdbz.jpg', 'Not a night scene. Centuries of darkened varnish produced the nickname, and cleaning revealed broad daylight. It has also been physically abused: strips were sawn off all four sides in 1715 to fit it between two doors, and the offcuts were discarded. It was slashed with a knife in 1911, slashed again in 1975, and had acid thrown at it in 1990. The 2019 restoration was livestreamed and a missing strip was reconstructed by AI.', 'Q219831', true),
('6fe8wrqcec', '1645-georges-de-la-tour-the-newborn', 'The Newborn', 'Georges de La Tour', 1645, 'c. 1645-1648', 'Baroque', 'oil on canvas', 'Musée des Beaux-Arts, Rennes', 3, false, 'object', 'https://nambatu.github.io/circart-preview/art/6fe8wrqcec.jpg', 'Lit by a single candle that La Tour hides behind a hand, so the light source is present but invisible, a device he used so consistently it functions as a signature. There is no halo and no angel, and scholars still argue whether it is a nativity or simply a baby. He was completely forgotten for nearly three centuries, rediscovered in 1915, and there are still fewer than fifty paintings securely attributed to him.', 'Q8774031', true),
('358kcshwgs', '1650-diego-velazquez-portrait-of-pope-innocent-x', 'Portrait of Pope Innocent X', 'Diego Velázquez', 1650, null, 'Baroque', 'oil on canvas', 'Galleria Doria Pamphilj, Rome', 2, false, 'object', 'https://nambatu.github.io/circart-preview/art/358kcshwgs.jpg', 'The Pope''s reported verdict was that it was too true, and the Pamphilj family have kept it in their palace ever since rather than let it go. Velázquez painted it during a buying trip to Rome for the Spanish king, and warmed up by painting his enslaved assistant Juan de Pareja, whom he freed shortly afterwards. The portrait haunted Francis Bacon, who made around forty-five screaming variations on it and never once went to see the original.', null, true),
('d3recxtpqx', '1655-jacob-van-ruisdael-jewish-cemetery-detroit', 'The Jewish Cemetery (Detroit version)', 'Jacob van Ruisdael', 1655, 'c. 1654-55; a second, smaller version is in Dresden', 'Dutch Golden Age', 'oil on canvas', 'Detroit Institute of Arts', 3, false, 'object', 'https://nambatu.github.io/circart-preview/art/d3recxtpqx.jpg', 'Ruisdael painted the Portuguese Jewish cemetery at Ouderkerk twice, and this is the larger of the two. He drew the tombs accurately enough that individual graves have been identified, then invented everything around them: the ruined church, the dead tree, the torrent and the rainbow exist nowhere on the site. So a real historical record sits inside a completely fabricated landscape, which is the whole argument of the picture, that documented lives get swallowed by time anyway. Goethe wrote an essay praising it. Ruisdael was the most influential landscape painter of the Dutch Golden Age and died in relative obscurity.', null, true),
('7f9mh4bvz4', '1656-diego-velazquez-las-meninas', 'Las Meninas', 'Diego Velázquez', 1656, null, 'Baroque', 'oil on canvas', 'Museo del Prado, Madrid', 1, false, 'object', 'https://nambatu.github.io/circart-preview/art/7f9mh4bvz4.jpg', 'Velázquez painted himself painting, on a canvas whose front we never see, while the king and queen appear only as a small blurred reflection in the mirror at the back, which means the royal couple are standing roughly where you are. Foucault opened The Order of Things with an extended analysis of it. The red cross of the Order of Santiago on Velázquez''s chest was added after his death, once he had finally been granted the knighthood he spent years pursuing.', null, true),
('2svw7g9q6z', '1658-johannes-vermeer-the-milkmaid', 'The Milkmaid', 'Johannes Vermeer', 1658, 'c. 1658-1661', 'Dutch Golden Age', 'oil on canvas', 'Rijksmuseum, Amsterdam', 1, false, 'object', 'https://nambatu.github.io/circart-preview/art/2svw7g9q6z.jpg', 'X-rays show Vermeer painted out a large wall map and a laundry basket to leave the plain, empty wall that makes the picture work. The bread crust is built from dabs of thick paint with tiny highlights, a technique so distinctive it has its own name. Vermeer produced perhaps 35 paintings in his whole life, died in debt at 43 leaving eleven children, and his widow had to hand paintings to the baker to settle the bread bill.', 'Q167605', true),
('ct2j5yvjmb', '1658-pieter-de-hooch-the-courtyard-of-a-house-in-delf', 'The Courtyard of a House in Delft', 'Pieter de Hooch', 1658, null, 'Dutch Golden Age', 'oil on canvas', 'National Gallery, London', 3, false, 'object', 'https://nambatu.github.io/circart-preview/art/ct2j5yvjmb.jpg', 'De Hooch''s whole speciality was the view through a doorway into a second, brighter space, and he arguably did it better than Vermeer before Vermeer did it at all. The stone tablet above the arch is a real one, salvaged from a demolished monastery, and it still exists. His late Amsterdam work declined sharply and he died in an insane asylum, after which his reputation was so low that dealers forged Vermeer signatures onto his paintings.', 'Q7727872', true),
('4jz2ah5m5r', '1665-johannes-vermeer-girl-with-a-pearl-earring', 'Girl with a Pearl Earring', 'Johannes Vermeer', 1665, 'c. 1665', 'Dutch Golden Age', 'oil on canvas', 'Mauritshuis, The Hague', 1, false, 'object', 'https://nambatu.github.io/circart-preview/art/4jz2ah5m5r.jpg', 'Not a portrait but a tronie, a study of a character type, which is why she has no name and no attributes. The pearl is almost certainly glass, and it is painted with roughly two strokes. In 1881 it sold at auction for about two guilders, roughly the price of a meal, because it was filthy and the buyer suspected it might be worth restoring. He was right. Recent scanning found eyelashes and a green curtain behind her, both long since faded.', 'Q185372', true),
('8f7esd2uqj', '1666-johannes-vermeer-the-art-of-painting', 'The Art of Painting', 'Johannes Vermeer', 1666, 'c. 1666-1668', 'Dutch Golden Age', 'oil on canvas', 'Kunsthistorisches Museum, Vienna', 3, false, 'object', 'https://nambatu.github.io/circart-preview/art/8f7esd2uqj.jpg', 'Vermeer never sold it, despite serious debt, which suggests it functioned as a showroom piece. His widow tried to transfer it to her mother to keep it from creditors and the courts blocked her. Its later career is worse: Hitler bought it in 1940 for his planned museum at Linz, it went into the salt mines, and Austria kept it after the war on the grounds that the sale had been technically legal.', 'Q588695', true),
('mpehacxb5t', '1668-jan-steen-the-merry-family', 'The Merry Family', 'Jan Steen', 1668, null, 'Dutch Golden Age', 'oil on canvas', 'Rijksmuseum, Amsterdam', 3, false, 'object', 'https://nambatu.github.io/circart-preview/art/mpehacxb5t.jpg', 'The Dutch phrase for a chaotic household is still a Jan Steen home, which is a rare case of a painter becoming an idiom. The note hanging above the scene spells out the moral: as the old sing, so the young pipe. Everyone is drinking, including the children. Steen also ran a brewery and later a tavern, which he was apparently better at painting than operating.', null, true),
('2sekd8bwhn', '1669-rembrandt-the-return-of-the-prodigal-son', 'The Return of the Prodigal Son', 'Rembrandt', 1669, 'c. 1661-1669', 'Dutch Golden Age', 'oil on canvas', 'Hermitage, Saint Petersburg', 2, false, 'object', 'https://nambatu.github.io/circart-preview/art/2sekd8bwhn.jpg', 'Finished in the year Rembrandt died, by which point he had been declared insolvent, sold his house and collection, buried his partner Hendrickje and his son Titus, and was living in rented rooms. The father''s two hands are painted differently, one broader and one finer, and generations of viewers have read them as one masculine and one maternal. Whether Rembrandt intended that or simply left it unfinished is genuinely unresolved.', 'Q512755', true),
('dyahhfkufn', '1670-bartolome-esteban-murillo-the-young-beggar', 'The Young Beggar', 'Bartolomé Esteban Murillo', 1670, 'c. 1645-1650', 'Baroque', 'oil on canvas', 'Louvre, Paris', 3, false, 'object', 'https://nambatu.github.io/circart-preview/art/dyahhfkufn.jpg', 'Murillo''s street children were painted for a Seville market that wanted charm, and this one is picking lice off himself in a shaft of sunlight. Seville had just been devastated by plague, losing perhaps half its population, so the picturesque urchin genre arrived in a city full of actual orphans. Murillo was so popular in the eighteenth century that he briefly outranked Velázquez, and the twentieth century punished him for it.', null, true),
('vdswc6skcc', '1717-antoine-watteau-the-embarkation-for-cythera', 'The Embarkation for Cythera', 'Antoine Watteau', 1717, null, 'Rococo', 'oil on canvas', 'Louvre, Paris', 2, false, 'object', 'https://nambatu.github.io/circart-preview/art/vdswc6skcc.jpg', 'Submitted as Watteau''s reception piece for the French Academy, which had no existing category that fitted it, so they invented one, the fête galante, specifically for him. Nobody agrees whether the elegant couples are departing for the island of love or reluctantly leaving it, and the ambiguity is presumably deliberate. Watteau was tubercular, difficult, and destroyed work he disliked. He died at 36 and the genre invented for him largely died with him.', 'Q531329', true),
('tycgext8s8', '1721-antoine-watteau-pierrot', 'Pierrot', 'Antoine Watteau', 1721, 'c. 1718-1719', 'Rococo', 'oil on canvas', 'Louvre, Paris', 3, false, 'object', 'https://nambatu.github.io/circart-preview/art/tycgext8s8.jpg', 'Probably painted as a signboard for a Paris café run by a retired actor, which would make one of the Louvre''s treasures a piece of shop advertising. The clown stands facing us, arms limp, entirely alone despite being surrounded by his own troupe, who are ignoring him. Watteau died of tuberculosis the same year at 36. The painting was long known as Gilles, a name a later owner appears to have invented.', 'Q3387944', true),
('vbmxq69nq9', '1728-jean-simeon-chardin-the-ray', 'The Ray', 'Jean-Siméon Chardin', 1728, null, 'Rococo', 'oil on canvas', 'Louvre, Paris', 3, false, 'object', 'https://nambatu.github.io/circart-preview/art/vbmxq69nq9.jpg', 'A gutted fish hanging on a hook, a cat picking its way toward some oysters, and this got Chardin admitted to the Academy on the spot. Diderot said it made every other still life in the room look like paint. The ray''s exposed viscera resolve, from a distance, into something disturbingly like a human face, which Matisse and Soutine both noticed and copied. Chardin painted slowly, exhibited little and never travelled.', null, true),
('6ybzwcaz9b', '1735-william-hogarth-a-rakes-progress-viii', 'A Rake''s Progress VIII: The Madhouse', 'William Hogarth', 1735, 'paintings executed c. 1732-34; engravings published 1735', 'Rococo', 'oil on canvas', 'Sir John Soane''s Museum, London', 2, false, 'object', 'https://nambatu.github.io/circart-preview/art/6ybzwcaz9b.jpg', 'The final plate of eight, in which the rake ends chained and half-naked on the floor of Bethlem Hospital, the asylum Londoners called Bedlam, surrounded by other inmates and by two fashionable women who have paid to come and look at them, because visiting the madhouse was a genuine day out. Hogarth made his real money from the engravings rather than the paintings, and lobbied Parliament so hard for protection against print piracy that the resulting 1735 copyright act is still nicknamed Hogarth''s Act. Sir John Soane bought the whole series and it still hangs, tightly packed, in his house museum in London.', null, true),
('d9xz8r7kah', '1743-william-hogarth-marriage-a-la-mode-ii', 'Marriage A-la-Mode II: The Tete a Tete', 'William Hogarth', 1743, 'series of six painted c. 1743-45', 'Rococo', 'oil on canvas', 'National Gallery, London', 3, false, 'object', 'https://nambatu.github.io/circart-preview/art/d9xz8r7kah.jpg', 'The second of six panels, the morning after: the husband slumped with a dog pulling a woman''s cap from his pocket, the wife stretching over an unpaid card game, and the steward walking out with a fistful of bills and one receipt. The series is a satire on marrying for money that ends in syphilis, a duel, a murder and a suicide, and the medical detail is accurate enough that historians use it as a source on eighteenth-century venereal disease: the black patches on several necks are syphilitic sores. Hogarth priced the prints for the middle classes he was warning. The paintings themselves sold badly at auction.', 'Q3944145', true),
('w4c77badfc', '1750-thomas-gainsborough-mr-and-mrs-andrews', 'Mr and Mrs Andrews', 'Thomas Gainsborough', 1750, null, 'Rococo', 'oil on canvas', 'National Gallery, London', 2, false, 'object', 'https://nambatu.github.io/circart-preview/art/w4c77badfc.jpg', 'Gainsborough was 23 and painting his neighbours, who wanted their land in the picture at least as much as themselves. The unfinished patch in Mrs Andrews''s lap was almost certainly left for a child that never arrived, or possibly a shot pheasant. John Berger used this painting in Ways of Seeing as his central example of portraiture as property record, and that reading has stuck to it permanently.', 'Q1619527', true),
('nhfbmgg4fk', '1755-canaletto-the-bucintoro-returning-to-the-m', 'The Bucintoro Returning to the Molo', 'Canaletto', 1755, 'c. 1730s', 'Vedutismo', 'oil on canvas', 'various collections', 3, false, 'object', 'https://nambatu.github.io/circart-preview/art/nhfbmgg4fk.jpg', 'Canaletto used a camera obscura, and his surviving sketchbook shows the traced outlines. He also cheated relentlessly, widening canals and moving buildings to improve the composition, so his Venice is a slightly better Venice than the real one. Almost his entire output went to English tourists on the Grand Tour, which is why there is more Canaletto in Britain than in Italy. He spent nine years living in London.', null, true),
('6xs5w2ajd7', '1767-jean-honore-fragonard-the-swing', 'The Swing', 'Jean-Honoré Fragonard', 1767, null, 'Rococo', 'oil on canvas', 'Wallace Collection, London', 1, false, 'object', 'https://nambatu.github.io/circart-preview/art/6xs5w2ajd7.jpg', 'The original patron reportedly wanted a bishop pushing the swing while he himself watched from below. The first painter approached refused in horror and passed the commission on; Fragonard took it, swapped the bishop for an oblivious husband, and delivered one of the great pieces of eighteenth-century innuendo. The shoe flying off, the statue with its finger to its lips, the sightline up the skirt: none of it is accidental.', null, true),
('gy54p5r8ru', '1768-joseph-wright-of-derby-an-experiment-on-a-bird-in-the-a', 'An Experiment on a Bird in the Air Pump', 'Joseph Wright of Derby', 1768, null, 'Enlightenment', 'oil on canvas', 'National Gallery, London', 2, false, 'object', 'https://nambatu.github.io/circart-preview/art/gy54p5r8ru.jpg', 'A travelling scientific demonstration lit like a Caravaggio altarpiece, frozen at the moment the showman''s hand rests on the valve and the audience must decide whether the bird lives. Wright of Derby was painting the Industrial Revolution as it happened, for the industrialists who were causing it, and his friends included Josiah Wedgwood and Erasmus Darwin. The one figure looking out the window is watching the moon, not the bird.', 'Q1167796', true),
('uvmtxxutgk', '1781-henry-fuseli-the-nightmare', 'The Nightmare', 'Henry Fuseli', 1781, null, 'Romanticism', 'oil on canvas', 'Detroit Institute of Arts', 2, false, 'object', 'https://nambatu.github.io/circart-preview/art/uvmtxxutgk.jpg', 'Freud kept a reproduction in his Vienna consulting room. The painting was an instant sensation, mass-produced as a print, and satirised in political cartoons within a couple of years, making it one of the first genuine horror images in Western art. On the back of the canvas is an unrelated portrait of a young woman, thought to be someone who rejected Fuseli, which has fed two centuries of speculation.', 'Q2317837', true),
('aq838qeegb', '1784-jacques-louis-david-oath-of-the-horatii', 'Oath of the Horatii', 'Jacques-Louis David', 1784, null, 'Neoclassicism', 'oil on canvas', 'Louvre, Paris', 2, false, 'object', 'https://nambatu.github.io/circart-preview/art/aq838qeegb.jpg', 'Painted in Rome, five years before the Revolution, and read afterwards as a summons to it, though David was working for the king''s household at the time. The men are all rigid straight lines and the women all collapsing curves, which is either brilliant compositional rhetoric or the most efficient sexism in French painting. David went on to vote for the execution of Louis XVI, run the visual propaganda of the Revolution, and then work for Napoleon.', 'Q476458', true),
('sw7dzya8ya', '1787-elisabeth-vigee-le-brun-self-portrait-with-her-daughter', 'Self-Portrait with Her Daughter Julie', 'Élisabeth Vigée Le Brun', 1787, null, 'Neoclassicism', 'oil on canvas', 'Louvre, Paris', 3, false, 'object', 'https://nambatu.github.io/circart-preview/art/sw7dzya8ya.jpg', 'Criticised at the Salon because she was showing her teeth, which portraits simply did not do. Vigée Le Brun was Marie Antoinette''s favourite painter, fled France on the night of the royal family''s arrest, and spent twelve years working her way across Italy, Austria and Russia, where she was in constant demand. She painted around 660 portraits, wrote lively memoirs, and was one of very few women admitted to the French Academy.', null, true),
('z6jf8qy775', '1793-jacques-louis-david-the-death-of-marat', 'The Death of Marat', 'Jacques-Louis David', 1793, null, 'Neoclassicism', 'oil on canvas', 'Royal Museums of Fine Arts, Brussels', 1, false, 'object', 'https://nambatu.github.io/circart-preview/art/z6jf8qy775.jpg', 'David was Marat''s friend and political ally and painted this within days of the murder, editing out the disfiguring skin condition that had put Marat in the bath in the first place. The result is a secular pietà with a wooden crate for a tombstone. It hung in the Convention as state propaganda until the political weather changed, after which it was quietly returned to David and kept out of sight for decades.', 'Q636537', true),
('zv92mek2zp', '1794-kitagawa-utamaro-three-beauties-of-the-present-da', 'Three Beauties of the Present Day', 'Kitagawa Utamaro', 1794, null, 'Ukiyo-e', 'woodblock print', 'various collections', 3, false, 'object', 'https://nambatu.github.io/circart-preview/art/zv92mek2zp.jpg', 'Three real, named women, a teahouse waitress and two geishas, drawn so nearly identically that only the crests on their kimonos distinguish them, which is a fair summary of how the pleasure districts marketed people. Utamaro was later punished by the shogunate for a print involving a historical warlord, spent time in manacles, and died shortly after. Japanese prints of this kind were cheap, disposable and used as packing material in export crates, which is roughly how Europe found them.', 'Q18210019', true),
('ya9b2k3gt3', '1797-francisco-goya-the-sleep-of-reason-produces-mon', 'The Sleep of Reason Produces Monsters', 'Francisco Goya', 1797, 'c. 1797-1799', 'Romanticism', 'aquatint etching', 'various collections', 2, false, 'object', 'https://nambatu.github.io/circart-preview/art/ya9b2k3gt3.jpg', 'Goya put the whole print series on sale in a perfume shop and withdrew it after two days, fearing the Inquisition, which had recently been prosecuting people for far less. Only about 27 sets sold. The title inscription is deliberately double-edged in Spanish: sueño means both sleep and dream, so reason is either dozing off or actively dreaming these things. He was going deaf by this point and the work turns darker every year afterwards.', 'Q671237', true),
('4csg2edje8', '1800-francisco-goya-the-nude-maja', 'The Nude Maja', 'Francisco Goya', 1800, 'c. 1797-1800', 'Romanticism', 'oil on canvas', 'Museo del Prado, Madrid', 2, true, 'object', 'https://nambatu.github.io/circart-preview/art/4csg2edje8.jpg', 'The Inquisition summoned Goya to explain who commissioned it and why, and he appears to have simply refused to say. It is among the first Western paintings of a nude woman with visible pubic hair and no mythological alibi whatsoever, which is what made it prosecutable. A clothed version of the same pose exists, and legend has it the two were mounted on a mechanism so one could be swapped for the other in front of visitors.', 'Q152867', true),
('73rvecx9jg', '1801-jacques-louis-david-napoleon-crossing-the-alps', 'Napoleon Crossing the Alps', 'Jacques-Louis David', 1801, null, 'Neoclassicism', 'oil on canvas', 'Château de Malmaison, France', 2, false, 'object', 'https://nambatu.github.io/circart-preview/art/73rvecx9jg.jpg', 'Napoleon actually crossed on a mule led by a guide, in bad weather, and refused to sit for the portrait, telling David that nobody knows what great men looked like and it is enough that the picture exists. So David painted a rearing stallion and put Bonaparte''s name carved into the rock next to Hannibal''s and Charlemagne''s. There are five versions. Paul Delaroche later painted the mule version out of spite, more or less.', 'Q59201', true),
('9md59zrdzk', '1808-caspar-david-friedrich-the-cross-in-the-mountains', 'The Cross in the Mountains', 'Caspar David Friedrich', 1808, null, 'Romanticism', 'oil on canvas', 'Gemäldegalerie, Dresden', 3, false, 'object', 'https://nambatu.github.io/circart-preview/art/9md59zrdzk.jpg', 'Caused a public scandal because Friedrich put a landscape on an altar, which meant treating mountains and fir trees as fit objects of worship. A critic wrote a furious attack arguing that landscape painting had no business creeping into churches; Friedrich replied in print. He painted almost no people from the front, worked from drawings rather than outdoors, and lived a reclusive, depressive life in Dresden, where he was eventually forgotten before his rediscovery around 1900.', 'Q884782', true),
('e3wva7a6h5', '1814-francisco-goya-the-third-of-may-1808', 'The Third of May 1808', 'Francisco Goya', 1814, null, 'Romanticism', 'oil on canvas', 'Museo del Prado, Madrid', 1, false, 'object', 'https://nambatu.github.io/circart-preview/art/e3wva7a6h5.jpg', 'Painted six years after the executions, once the French had gone and commemorating Spanish resistance was no longer a hanging offence. The man in the white shirt has stigmata on his raised palm. The firing squad has no faces, just a wall of backs and a hedge of barrels, which is the invention everyone else copied afterwards, from Manet to Picasso. The Prado kept it rolled up and unexhibited for decades after Goya''s death.', 'Q1091086', true),
('bzujucrgsx', '1814-jean-auguste-dominique-ingres-la-grande-odalisque', 'La Grande Odalisque', 'Jean-Auguste-Dominique Ingres', 1814, null, 'Neoclassicism', 'oil on canvas', 'Louvre, Paris', 2, false, 'object', 'https://nambatu.github.io/circart-preview/art/bzujucrgsx.jpg', 'Critics counted three vertebrae too many in her back and said so loudly at the Salon. Ingres did not care: he stretched, smoothed and rearranged anatomy in service of line, and her right arm has no plausible elbow either. The painting was commissioned by Napoleon''s sister and never paid for. Ingres considered himself a serious history painter and was privately irritated that the public preferred these.', 'Q1978815', true),
('5t2zrhnc2m', '1818-caspar-david-friedrich-wanderer-above-the-sea-of-fog', 'Wanderer above the Sea of Fog', 'Caspar David Friedrich', 1818, null, 'Romanticism', 'oil on canvas', 'Kunsthalle Hamburg', 1, false, 'object', 'https://nambatu.github.io/circart-preview/art/5t2zrhnc2m.jpg', 'The most reproduced image in German Romanticism, and we never see the man''s face, which is precisely why it works as a book cover, an album sleeve and a thousand motivational posters. Friedrich was painting in a Germany occupied and then reshaped by Napoleon, and the figure wears old German dress, a quietly nationalist costume at the time. He suffered a stroke in 1835 and could no longer paint in oils.', 'Q311243', true),
('utdw4tp4dq', '1819-theodore-gericault-the-raft-of-the-medusa', 'The Raft of the Medusa', 'Théodore Géricault', 1819, null, 'Romanticism', 'oil on canvas', 'Louvre, Paris', 1, false, 'object', 'https://nambatu.github.io/circart-preview/art/utdw4tp4dq.jpg', 'Géricault interviewed the survivors, had the ship''s carpenter build him a scale model of the raft, borrowed severed limbs from a hospital to study decomposition, and kept them in his studio until the smell drove visitors out. 147 people were put on the raft; 15 survived, having resorted to cannibalism. The wreck was a political scandal because the captain was an unqualified royalist appointee. Géricault was 27 and died five years later after a riding accident.', null, true),
('9pz54drgv8', '1821-john-constable-the-hay-wain', 'The Hay Wain', 'John Constable', 1821, null, 'Romanticism', 'oil on canvas', 'National Gallery, London', 2, false, 'object', 'https://nambatu.github.io/circart-preview/art/9pz54drgv8.jpg', 'Ignored in England, where it failed to sell, and then awarded a gold medal in Paris in 1824, where it startled Delacroix so much that he reportedly went home and repainted the background of his own Salon entry. Constable never left England, painted the same few square miles of Suffolk obsessively, and only got elected to the Royal Academy at 52. The cart is standing in the water to swell the wooden wheels so they stay tight.', 'Q2366825', true),
('xmmx5sq9ua', '1823-francisco-goya-saturn-devouring-his-son', 'Saturn Devouring His Son', 'Francisco Goya', 1823, 'c. 1819-1823', 'Romanticism', 'mixed media on plaster', 'Museo del Prado, Madrid', 1, true, 'object', 'https://nambatu.github.io/circart-preview/art/xmmx5sq9ua.jpg', 'Painted directly onto the plaster walls of Goya''s own farmhouse, in a series known as the Black Paintings, and never meant to be seen by anyone. He was in his mid-seventies, deaf, ill and politically frightened. They were transferred to canvas fifty years later in a brutal operation that damaged them badly, and photographs from before the transfer show significant differences. Whether the figure was originally so wild-eyed is genuinely uncertain.', 'Q1150997', true),
('wmxdspqb5h', '1824-caspar-david-friedrich-the-sea-of-ice', 'The Sea of Ice', 'Caspar David Friedrich', 1824, null, 'Romanticism', 'oil on canvas', 'Kunsthalle Hamburg', 3, false, 'object', 'https://nambatu.github.io/circart-preview/art/wmxdspqb5h.jpg', 'A ship crushed to splinters under slabs of ice, with barely any of it visible, painted after Friedrich studied ice floes on the frozen Elbe. Nobody would buy it in his lifetime and it stayed in his studio. It has been read as a response to a failed Arctic expedition and as a political allegory about crushed liberal hopes in Germany, and it looks about ninety years ahead of its time in either case.', 'Q194137', true),
('zxbyc8cc3e', '1830-eugene-delacroix-liberty-leading-the-people', 'Liberty Leading the People', 'Eugène Delacroix', 1830, null, 'Romanticism', 'oil on canvas', 'Louvre, Paris', 1, false, 'object', 'https://nambatu.github.io/circart-preview/art/zxbyc8cc3e.jpg', 'Commemorates the July Revolution of 1830, not 1789, a distinction almost everyone gets wrong. The new government bought it and then hid it, correctly judging that a bare-breasted woman leading an armed mob over corpses might give people ideas. Delacroix wrote to his brother that if he had not fought for his country, he would at least paint for it. The man in the top hat is not, despite persistent legend, Delacroix himself.', null, true),
('684rpf2dwk', '1831-katsushika-hokusai-the-great-wave-off-kanagawa', 'The Great Wave off Kanagawa', 'Katsushika Hokusai', 1831, 'c. 1830-1832', 'Ukiyo-e', 'woodblock print', 'various collections', 1, false, 'object', 'https://nambatu.github.io/circart-preview/art/684rpf2dwk.jpg', 'Hokusai was around 70 and using imported Prussian blue, a synthetic pigment newly available in Japan and cheap enough for mass-market prints, without which the image does not exist. Thousands of impressions were pulled, sold for roughly the price of a bowl of noodles. The boats are cargo vessels carrying fish to Edo, and the wave is technically a rogue wave rather than a tsunami. Hokusai changed his professional name over thirty times.', 'Q252485', true),
('uscf5g4qb4', '1832-katsushika-hokusai-fine-wind-clear-morning', 'Fine Wind, Clear Morning', 'Katsushika Hokusai', 1832, 'c. 1830-1832', 'Ukiyo-e', 'woodblock print', 'various collections', 3, false, 'object', 'https://nambatu.github.io/circart-preview/art/uscf5g4qb4.jpg', 'Known everywhere as Red Fuji. The colour only appears for a few days in early autumn when clear conditions and low sun catch the mountain at dawn, so the print records a genuine and rare meteorological event. Early impressions have a white sky and a deep red mountain; later ones fade toward pink because the pigment was fugitive, which means the price of a copy depends heavily on how red it still is.', 'Q3565037', true),
('67qyextf2w', '1838-j-m-w-turner-the-fighting-temeraire', 'The Fighting Temeraire', 'J.M.W. Turner', 1838, null, 'Romanticism', 'oil on canvas', 'National Gallery, London', 2, false, 'object', 'https://nambatu.github.io/circart-preview/art/67qyextf2w.jpg', 'A veteran warship of Trafalgar being towed to the breaker''s yard by a squat, filthy steam tug, and Turner rigged the scene shamelessly: the ship had already been stripped of masts, the tug is on the wrong side, and the sunset is in the wrong direction for the journey. He refused every offer to sell it, calling it his darling, and left it to the nation. Voted Britain''s favourite painting in a 2005 poll.', null, true),
('zny9xafbkx', '1844-j-m-w-turner-rain-steam-and-speed', 'Rain, Steam and Speed', 'J.M.W. Turner', 1844, null, 'Romanticism', 'oil on canvas', 'National Gallery, London', 2, false, 'object', 'https://nambatu.github.io/circart-preview/art/zny9xafbkx.jpg', 'The Great Western Railway had opened six years earlier and was still genuinely alarming, and Turner puts you on the tracks. There is a hare running ahead of the train, easy to miss, which is either a comment on speed or a small joke about what the train is about to do to it. Turner was 69. A contemporary story, probably apocryphal, has him sticking his head out of a train window in a storm for nine minutes to observe.', null, true),
('g98bb4z5ze', '1849-gustave-courbet-the-stone-breakers', 'The Stone Breakers', 'Gustave Courbet', 1849, null, 'Realism', 'oil on canvas', 'destroyed 1945', 3, false, 'destroyed_or_lost', 'https://nambatu.github.io/circart-preview/art/g98bb4z5ze.jpg', 'Destroyed in the bombing of Dresden in 1945, so it survives only in photographs, which makes one of the founding paintings of Realism a picture nobody alive has seen. Courbet painted two anonymous roadside labourers at the scale reserved for kings and battles, showed neither face, and refused to sentimentalise them. Proudhon claimed it as socialism. Courbet said he had simply seen the men on the road and asked them to come to his studio.', 'Q2914912', true),
('ystbdcxdmc', '1850-gustave-courbet-a-burial-at-ornans', 'A Burial at Ornans', 'Gustave Courbet', 1850, 'c. 1849-1850', 'Realism', 'oil on canvas', 'Musée d''Orsay, Paris', 2, false, 'object', 'https://nambatu.github.io/circart-preview/art/ystbdcxdmc.jpg', 'Courbet painted forty-odd villagers from his provincial home town, life-size, on a canvas over six metres wide, at a scale previously reserved for coronations and battles. Critics were insulted on behalf of art. The grave is open at the front, the dog is distracted, and nobody is visibly grieving with any dignity. He submitted it under the deliberately flat title A Painting of Human Figures, the History of a Burial at Ornans.', 'Q540488', true),
('jfhbnufbqh', '1852-john-everett-millais-ophelia', 'Ophelia', 'John Everett Millais', 1852, null, 'Pre-Raphaelite', 'oil on canvas', 'Tate Britain, London', 1, false, 'object', 'https://nambatu.github.io/circart-preview/art/jfhbnufbqh.jpg', 'The model, Elizabeth Siddal, lay in a bathtub kept warm by oil lamps underneath. The lamps went out, Millais painted on without noticing, and she caught a severe illness. Her father sent Millais a doctor''s bill, which he paid. Millais had earlier spent five months painting the riverbank outdoors, plant by plant, and botanists can identify every species. Siddal later married Rossetti and died of a laudanum overdose at 32.', 'Q1065493', true),
('quav6rnnk4', '1857-jean-francois-millet-the-gleaners', 'The Gleaners', 'Jean-François Millet', 1857, null, 'Realism', 'oil on canvas', 'Musée d''Orsay, Paris', 2, false, 'object', 'https://nambatu.github.io/circart-preview/art/quav6rnnk4.jpg', 'Read at the Salon as dangerous socialism, because it dignified the poorest legal right in French agriculture: the right of the landless to pick over a field after harvest. Millet gave three stooping women the monumentality of classical sculpture and put a rich, overflowing harvest in the background to make the contrast unmissable. Critics called it the three fates of poverty. Van Gogh copied Millet obsessively for years.', null, true),
('jzwcrje5wr', '1857-utagawa-hiroshige-sudden-shower-over-shin-ohashi-b', 'Sudden Shower over Shin-Ohashi Bridge', 'Utagawa Hiroshige', 1857, null, 'Ukiyo-e', 'woodblock print', 'various collections', 3, false, 'object', 'https://nambatu.github.io/circart-preview/art/jzwcrje5wr.jpg', 'Van Gogh copied this print in oils almost line for line in 1887, including the Japanese characters in the border, which he could not read. Hiroshige''s rain is rendered as sharp diagonal lines cut into the woodblock, an effect that has no European precedent and which Impressionism absorbed wholesale. The series it comes from, One Hundred Famous Views of Edo, was made in the last years of his life and he died of cholera before finishing it.', 'Q5826309', true),
('bb5hnjmbzp', '1861-ferdinand-georg-waldmuller-early-spring-in-the-vienna-woods', 'Early Spring in the Vienna Woods', 'Ferdinand Georg Waldmüller', 1861, null, 'Biedermeier', 'oil on panel', 'Belvedere, Vienna', 3, false, 'object', 'https://nambatu.github.io/circart-preview/art/bb5hnjmbzp.jpg', 'Waldmüller was suspended from the Vienna Academy and eventually forced into early retirement for insisting that students should paint outdoors from nature rather than copying casts and old masters. He published pamphlets attacking the Academy, which did not help. He was pardoned late in life, by which point he was painting these luminous, hyper-detailed forest scenes almost entirely for a private Biedermeier market that wanted exactly this.', null, true),
('gjhzvptnwx', '1863-edouard-manet-le-dejeuner-sur-l-herbe', 'Le Déjeuner sur l''herbe', 'Édouard Manet', 1863, null, 'Realism', 'oil on canvas', 'Musée d''Orsay, Paris', 1, true, 'object', 'https://nambatu.github.io/circart-preview/art/gjhzvptnwx.jpg', 'Rejected by the Salon and shown instead at the Salon des Refusés, an overflow exhibition the emperor set up after so many rejections caused an outcry, where crowds turned up specifically to laugh. The scandal was not the nudity, which was standard for mythological subjects, but that she is an identifiable contemporary woman sitting next to two clothed men in modern dress and looking straight out at you. The pose is lifted from a Raphael-derived engraving.', null, true),
('zacxuhytdt', '1863-edouard-manet-olympia', 'Olympia', 'Édouard Manet', 1863, null, 'Realism', 'oil on canvas', 'Musée d''Orsay, Paris', 1, true, 'object', 'https://nambatu.github.io/circart-preview/art/zacxuhytdt.jpg', 'Guards had to be posted to stop visitors attacking it with walking sticks when it was finally exhibited in 1865. The offence, again, was specificity: she is a working prostitute, the flowers are from a client, the black ribbon and single slipper are period signals everyone recognised, and she is looking directly at the viewer without shame. Manet based the pose on Titian''s Venus of Urbino, which everyone also recognised, and that made it worse.', null, true),
('9y2zv3e4ug', '1866-gustave-courbet-l-origine-du-monde', 'L''Origine du monde', 'Gustave Courbet', 1866, null, 'Realism', 'oil on canvas', 'Musée d''Orsay, Paris', 2, true, 'object', 'https://nambatu.github.io/circart-preview/art/9y2zv3e4ug.jpg', 'Commissioned by an Ottoman diplomat with an extensive erotic collection, then owned for decades by the psychoanalyst Jacques Lacan, who kept it behind a sliding wooden panel painted by André Masson so guests would not encounter it unprepared. It was not publicly exhibited until 1988 and entered the Musée d''Orsay in 1995. Facebook has repeatedly deleted posts of it, and a French teacher sued the company over the account suspension and won.', 'Q334138', true),
('yp9ugawx6b', '1867-claude-monet-women-in-the-garden', 'Women in the Garden', 'Claude Monet', 1867, null, 'Impressionism', 'oil on canvas', 'Musée d''Orsay, Paris', 3, false, 'object', 'https://nambatu.github.io/circart-preview/art/yp9ugawx6b.jpg', 'Monet dug a trench in the garden with a pulley system so he could raise and lower the enormous canvas and paint every part of it outdoors at the correct eye level, which is either commitment or madness. The Salon rejected it. He was 26, broke, and Camille modelled for all four women. Manet reportedly disliked it. The French state finally bought it in 1921 for 200,000 francs.', 'Q2734892', true),
('by7tr894xp', '1871-james-mcneill-whistler-arrangement-in-grey-and-black-no', 'Arrangement in Grey and Black No. 1', 'James McNeill Whistler', 1871, null, 'Realism', 'oil on canvas', 'Musée d''Orsay, Paris', 1, false, 'object', 'https://nambatu.github.io/circart-preview/art/by7tr894xp.jpg', 'Whistler''s mother sat in for a model who failed to turn up, and Whistler spent the rest of his life insisting the subject was irrelevant and that the public had no business caring whose mother it was. He wanted it read as an arrangement of tones. The public ignored him completely and turned it into the definitive image of motherhood, put it on a US postage stamp, and made it a punchline in Mr. Bean.', 'Q687182', true),
('asreeqmju6', '1872-claude-monet-impression-sunrise', 'Impression, Sunrise', 'Claude Monet', 1872, null, 'Impressionism', 'oil on canvas', 'Musée Marmottan Monet, Paris', 1, false, 'object', 'https://nambatu.github.io/circart-preview/art/asreeqmju6.jpg', 'A hostile critic named Louis Leroy wrote a mocking review built around the title, saying that wallpaper in its embryonic state was more finished, and coined Impressionism as an insult. The group adopted it within a couple of years. Astronomers have since analysed the tide, the smoke direction and the sun''s altitude and dated the scene to around 7:35am on 13 November 1872. It was stolen in 1985 and recovered five years later.', 'Q328523', true),
('2fa6jjjb5v', '1873-ilya-repin-barge-haulers-on-the-volga', 'Barge Haulers on the Volga', 'Ilya Repin', 1873, 'c. 1870-1873', 'Realism', 'oil on canvas', 'Russian Museum, Saint Petersburg', 3, false, 'object', 'https://nambatu.github.io/circart-preview/art/2fa6jjjb5v.jpg', 'Repin spent three summers living among the haulers, sketching them and learning their names, and several are identifiable individuals rather than types. He then sold the painting to the Tsar''s brother, which is the contradiction of Russian critical realism in one transaction. Dostoevsky praised it for showing the men''s dignity rather than begging for pity. Repin was 29 and it made his reputation instantly.', 'Q175628', true),
('s9ktetuzgy', '1875-thomas-eakins-the-gross-clinic', 'The Gross Clinic', 'Thomas Eakins', 1875, null, 'Realism', 'oil on canvas', 'Philadelphia Museum of Art', 3, false, 'object', 'https://nambatu.github.io/circart-preview/art/s9ktetuzgy.jpg', 'Rejected from the art section of the 1876 Centennial Exhibition as too gruesome and hung in the medical display instead, next to actual instruments. Eakins was documenting a real surgeon, Samuel Gross, mid-operation, with blood on his fingers and a woman recoiling in the corner. Eakins later lost his teaching job for removing a loincloth from a male model in a mixed class. Philadelphia raised $68 million in 2006 to stop the painting leaving the city.', 'Q1213936', true),
('zupj35xk53', '1876-edgar-degas-l-absinthe', 'L''Absinthe', 'Edgar Degas', 1876, null, 'Impressionism', 'oil on canvas', 'Musée d''Orsay, Paris', 3, false, 'object', 'https://nambatu.github.io/circart-preview/art/zupj35xk53.jpg', 'When shown in London in 1893 it was denounced as a warning against drink and as a slur on French morals, and critics attacked the models as degraded. Both were friends of Degas: an actress and an artist, neither of whom drank like this. The composition is radically off-balance, with the figures shoved right and a wedge of empty tables cutting in, which Degas learned partly from Japanese prints and partly from photography.', 'Q1239950', true),
('b4bggrx4hw', '1876-pierre-auguste-renoir-bal-du-moulin-de-la-galette', 'Bal du moulin de la Galette', 'Pierre-Auguste Renoir', 1876, null, 'Impressionism', 'oil on canvas', 'Musée d''Orsay, Paris', 1, false, 'object', 'https://nambatu.github.io/circart-preview/art/b4bggrx4hw.jpg', 'Renoir''s friends carried the large canvas up the Montmartre hill every morning so he could paint the open-air dance in the actual light, which is why the sunlight falls through the trees in dappled blue-violet blotches that critics complained looked like mould on the dancers. Most of the figures are his friends. It sold in 1990 for $78 million, then a record, to a Japanese businessman who said he wanted to be cremated with it and was talked out of it.', 'Q683274', true),
('qhv488nc9u', '1877-gustave-caillebotte-paris-street-rainy-day', 'Paris Street, Rainy Day', 'Gustave Caillebotte', 1877, null, 'Impressionism', 'oil on canvas', 'Art Institute of Chicago', 2, false, 'object', 'https://nambatu.github.io/circart-preview/art/qhv488nc9u.jpg', 'The Haussmann boulevards were barely twenty years old and had been driven through medieval Paris by demolishing whole neighbourhoods, so Caillebotte is painting brand-new urban space as if it were already ordinary. The perspective is photographic and the umbrella geometry is obsessive. Caillebotte was independently wealthy, bought his friends'' unsellable paintings to support them, and left the collection to France, which initially refused a large part of it.', 'Q1452762', true),
('cdvc8fpjv5', '1880-arnold-bocklin-isle-of-the-dead', 'Isle of the Dead', 'Arnold Böcklin', 1880, null, 'Symbolism', 'oil on canvas', 'various versions', 2, false, 'object', 'https://nambatu.github.io/circart-preview/art/cdvc8fpjv5.jpg', 'Böcklin painted five versions because people kept commissioning copies, and one client asked for a painting to dream over. Rachmaninoff wrote a tone poem after seeing a black and white reproduction and later said he preferred the reproduction to the original. Reproductions hung in Freud''s office and Lenin''s, and Hitler owned a version. Böcklin, asked to explain it, declined and said the viewer should be able to work it out.', null, true),
('uc9m3sdx2z', '1881-pierre-auguste-renoir-luncheon-of-the-boating-party', 'Luncheon of the Boating Party', 'Pierre-Auguste Renoir', 1881, null, 'Impressionism', 'oil on canvas', 'Phillips Collection, Washington', 1, false, 'object', 'https://nambatu.github.io/circart-preview/art/uc9m3sdx2z.jpg', 'The woman playing with the small dog is Aline Charigot, who would become Renoir''s wife. Almost everyone else is a friend: the man in the singlet at the left owned the restaurant, the man in the top hat was a collector, and the seated figure in the foreground is Caillebotte. Renoir hauled them back repeatedly across a summer. The restaurant on the Seine still exists and still serves lunch.', 'Q1167907', true),
('9hpbh2axx6', '1882-edouard-manet-a-bar-at-the-folies-bergere', 'A Bar at the Folies-Bergère', 'Édouard Manet', 1882, null, 'Impressionism', 'oil on canvas', 'Courtauld Gallery, London', 2, false, 'object', 'https://nambatu.github.io/circart-preview/art/9hpbh2axx6.jpg', 'The reflection is wrong and always has been. The barmaid''s mirrored back is displaced far to the right and the man she is talking to is not visible in front of her, which has generated a century of arguments about whether Manet made a mistake, moved the viewpoint deliberately, or was showing us what she sees rather than what is there. He was seriously ill by then and died the following year at 51.', null, true),
('pfzj7qfvkv', '1884-georges-seurat-bathers-at-asnieres', 'Bathers at Asnières', 'Georges Seurat', 1884, null, 'Neo-Impressionism', 'oil on canvas', 'National Gallery, London', 3, false, 'object', 'https://nambatu.github.io/circart-preview/art/pfzj7qfvkv.jpg', 'Painted opposite a factory district, showing working-class Parisians bathing downstream from the smokestacks, at exactly the spot where a wealthier crowd would not swim. Seurat was 24. He submitted it to the Salon, was rejected, and helped found an independent exhibiting society in response. The painting was reworked later with dots added in places, so you can see him inventing his own technique on top of an already finished picture.', 'Q1090837', true),
('ujkgtwf2v6', '1884-john-singer-sargent-portrait-of-madame-x', 'Portrait of Madame X', 'John Singer Sargent', 1884, null, 'Realism', 'oil on canvas', 'Metropolitan Museum of Art, New York', 2, false, 'object', 'https://nambatu.github.io/circart-preview/art/ujkgtwf2v6.jpg', 'The right shoulder strap originally hung off her arm, and the resulting scandal at the Salon was severe enough that her mother begged Sargent to withdraw it and Sargent left Paris for London. He repainted the strap upright afterwards. The sitter was an American socialite in Paris famous for her appearance, and the lavender-white skin is cosmetic, not invented. Sargent kept the painting for over thirty years and called it the best thing he had done.', null, true),
('s8pnye8kwy', '1886-auguste-rodin-the-kiss', 'The Kiss', 'Auguste Rodin', 1886, 'c. 1882-1889', 'Modern sculpture', 'marble', 'Musée Rodin, Paris', 2, false, 'public_sculpture', 'https://nambatu.github.io/circart-preview/art/s8pnye8kwy.jpg', 'The couple are Paolo and Francesca from Dante, adulterers murdered by her husband, and their lips do not actually touch, because Rodin is showing the instant before rather than the act. It was carved as part of a vast, never-completed doorway commission. Rodin himself came to dislike it, calling it a large sculpted knick-knack that followed the conventional formula. It was nonetheless copied in marble for wealthy buyers again and again.', 'Q2418237', true),
('cqvqnk2jvt', '1886-georges-seurat-a-sunday-afternoon-on-the-island', 'A Sunday Afternoon on the Island of La Grande Jatte', 'Georges Seurat', 1886, 'c. 1884-1886', 'Neo-Impressionism', 'oil on canvas', 'Art Institute of Chicago', 1, false, 'object', 'https://nambatu.github.io/circart-preview/art/cqvqnk2jvt.jpg', 'Seurat spent two years, made around sixty preparatory studies and painted it in millions of small dots based on contemporary colour theory, aiming for optical mixing in the viewer''s eye. The theory was partly wrong and the borders he later added have darkened. He was 26 and died five years later of an unidentified illness. Sondheim built an entire musical around it, and it has been parodied so often it functions as visual shorthand for painting itself.', 'Q1044742', true),
('gx8cehvfr2', '1888-john-william-waterhouse-the-lady-of-shalott', 'The Lady of Shalott', 'John William Waterhouse', 1888, null, 'Pre-Raphaelite', 'oil on canvas', 'Tate Britain, London', 2, false, 'object', 'https://nambatu.github.io/circart-preview/art/gx8cehvfr2.jpg', 'Painted more than thirty years after the Pre-Raphaelite Brotherhood dissolved, in a deliberately archaic style, at a moment when Paris was inventing Post-Impressionism. Waterhouse was commercially enormous and critically dismissed for most of the twentieth century. The Tennyson poem it illustrates involves a woman cursed to see the world only in a mirror, who dies for looking directly at it, and the three candles in the boat are dying with her.', 'Q2445726', true),
('6rrbwp5a8q', '1888-vincent-van-gogh-sunflowers', 'Sunflowers', 'Vincent van Gogh', 1888, null, 'Post-Impressionism', 'oil on canvas', 'National Gallery, London', 1, false, 'object', 'https://nambatu.github.io/circart-preview/art/6rrbwp5a8q.jpg', 'Painted to decorate the bedroom Gauguin would use in Arles, as a kind of welcome banner, in the weeks of frantic optimism before the arrangement collapsed catastrophically. Van Gogh used the new chrome yellow, which was cheap and unstable, and the flowers have been browning ever since; recent analysis shows the process is ongoing and irreversible. There are several versions. One was destroyed in Japan during the Second World War.', 'Q157541', true),
('awqtvmxeqr', '1888-vincent-van-gogh-cafe-terrace-at-night', 'Café Terrace at Night', 'Vincent van Gogh', 1888, null, 'Post-Impressionism', 'oil on canvas', 'Kröller-Müller Museum, Otterlo', 2, false, 'object', 'https://nambatu.github.io/circart-preview/art/awqtvmxeqr.jpg', 'The first canvas in which Van Gogh painted a night sky with stars, and he painted it outdoors after dark, reportedly by gaslight, which he wrote about with enormous enthusiasm to his sister. There is no black anywhere in it. The café still trades on the same spot in Arles and has been repainted yellow to match. He had arrived in Arles only months earlier expecting to found an artists'' colony.', 'Q1025704', true),
('9pwzh5hdpw', '1889-vincent-van-gogh-the-starry-night', 'The Starry Night', 'Vincent van Gogh', 1889, null, 'Post-Impressionism', 'oil on canvas', 'Museum of Modern Art, New York', 1, false, 'object', 'https://nambatu.github.io/circart-preview/art/9pwzh5hdpw.jpg', 'Painted from the barred window of the asylum at Saint-Rémy, before dawn, though the village below is invented and there are no cypresses that close to the building. Van Gogh himself considered it a failure and said so in a letter. Astronomers have identified Venus in the correct position for that morning. A 2006 fluid-dynamics paper argued the turbulence in the sky matches real mathematical models of turbulent flow, which nobody has satisfactorily explained.', 'Q45585', true),
('mjv66fpt2v', '1889-vincent-van-gogh-self-portrait-with-bandaged-ear', 'Self-Portrait with Bandaged Ear', 'Vincent van Gogh', 1889, null, 'Post-Impressionism', 'oil on canvas', 'Courtauld Gallery, London', 2, false, 'object', 'https://nambatu.github.io/circart-preview/art/mjv66fpt2v.jpg', 'Painted weeks after he cut off part of his own ear, with a Japanese print pinned on the wall behind him and an empty easel beside him. He is wearing a winter coat indoors, which suggests the studio was freezing. The bandage is on the right ear in the painting because he was working from a mirror; it was the left. He returned to work almost immediately and produced some of his best paintings over the following year.', 'Q19363211', true),
('tn7t6tjpp2', '1891-henri-de-toulouse-lautrec-moulin-rouge-la-goulue', 'Moulin Rouge: La Goulue', 'Henri de Toulouse-Lautrec', 1891, null, 'Post-Impressionism', 'lithograph poster', 'various collections', 2, false, 'object', 'https://nambatu.github.io/circart-preview/art/tn7t6tjpp2.jpg', 'Printed as a street poster in an edition of about 3,000 and pasted around Paris, where people peeled them off the walls overnight, which is why originals are scarce and expensive. It made Toulouse-Lautrec famous almost immediately. La Goulue, the Glutton, was a real dancer who reportedly drank from customers'' glasses as she passed; she later ran a failing fairground booth and died poor. Lautrec had a bone condition that stopped his legs growing and died at 36.', 'Q17026577', true),
('u45wge2ngc', '1892-henri-rousseau-tiger-in-a-tropical-storm', 'Tiger in a Tropical Storm', 'Henri Rousseau', 1892, null, 'Naive art', 'oil on canvas', 'National Gallery, London', 2, false, 'object', 'https://nambatu.github.io/circart-preview/art/u45wge2ngc.jpg', 'Rousseau was a Paris customs officer who never left France, and drew his jungles from the botanical gardens, illustrated magazines and the zoo. Critics savaged the painting. He explained the rain as diagonal silver threads because that is how he saw it, and painted the tiger with a fixed expression somewhere between rage and mild alarm. Picasso later bought a Rousseau for five francs from a dealer who was selling it to be painted over, and threw a famous banquet in his honour.', 'Q960447', true),
('g6vx5k7rdm', '1893-edvard-munch-the-scream', 'The Scream', 'Edvard Munch', 1893, null, 'Expressionism', 'tempera and crayon on cardboard', 'National Gallery, Oslo', 1, false, 'object', 'https://nambatu.github.io/circart-preview/art/g6vx5k7rdm.jpg', 'Munch''s diary records walking at sunset when the sky turned blood red and he felt an infinite scream passing through nature, and researchers have suggested the colour came from Krakatoa ash, which produced spectacular red skies over Europe for months. The figure is not screaming but blocking out a scream. In the top left corner, in tiny pencil, someone wrote that it could only have been painted by a madman; 2021 analysis confirmed the handwriting is Munch''s own.', 'Q471379', true),
('mjecpw8ba7', '1894-alphonse-mucha-gismonda', 'Gismonda', 'Alphonse Mucha', 1894, null, 'Art Nouveau', 'lithograph poster', 'various collections', 2, false, 'object', 'https://nambatu.github.io/circart-preview/art/mjecpw8ba7.jpg', 'Mucha was the only artist in the shop over Christmas when Sarah Bernhardt demanded a new poster urgently. He designed it in days, in an unusual tall narrow format because that was the paper available. Bernhardt saw it, loved it, and signed him to a six-year contract. Parisians began bribing bill-stickers or simply cutting the posters off walls at night. Mucha spent the rest of his life slightly resentful that this was what he was known for.', 'Q3107798', true),
('s77kt97v6u', '1895-paul-cezanne-the-card-players', 'The Card Players', 'Paul Cézanne', 1895, 'c. 1890-1895', 'Post-Impressionism', 'oil on canvas', 'Musée d''Orsay, Paris', 2, false, 'object', 'https://nambatu.github.io/circart-preview/art/s77kt97v6u.jpg', 'Cézanne made five versions and used local farm labourers from his family estate as models, paying them to sit for hours, which is why the smallest versions are the most concentrated. One version sold privately to Qatar around 2011 for a figure reported at over $250 million, then the highest price ever paid for a painting. Cézanne, who exhibited badly and was rejected repeatedly, died still believing he had not solved the problem he was working on.', null, true),
('hhp7ves5ds', '1897-henri-rousseau-the-sleeping-gypsy', 'The Sleeping Gypsy', 'Henri Rousseau', 1897, null, 'Naive art', 'oil on canvas', 'Museum of Modern Art, New York', 2, false, 'object', 'https://nambatu.github.io/circart-preview/art/hhp7ves5ds.jpg', 'Rousseau offered it to the mayor of his home town as the work of a local boy, suggesting a modest price. The mayor declined. The painting then vanished for nearly thirty years, resurfaced in 1924, and was dismissed by some experts as a forgery for decades afterwards. The lion is not attacking; it is sniffing. Rousseau described the scene in a letter with total literalness, as though reporting something he had witnessed.', 'Q1219263', true),
('vjm26zges4', '1897-paul-gauguin-where-do-we-come-from-what-are-w', 'Where Do We Come From? What Are We? Where Are We Going?', 'Paul Gauguin', 1897, 'c. 1897-1898', 'Post-Impressionism', 'oil on canvas', 'Museum of Fine Arts, Boston', 2, false, 'object', 'https://nambatu.github.io/circart-preview/art/vjm26zges4.jpg', 'Painted in Tahiti as an intended final testament, on coarse sacking because he could not afford proper canvas, and immediately afterwards Gauguin went into the hills and attempted suicide with arsenic. He survived, badly. He wrote that it should be read right to left, from the infant to the old woman. The romantic Tahitian narrative has been substantially reassessed: he was a European colonial who took teenage partners and infected them.', 'Q890678', true),
('t4apnjmvss', '1899-gustav-klimt-nuda-veritas', 'Nuda Veritas', 'Gustav Klimt', 1899, null, 'Art Nouveau', 'oil on canvas', 'Austrian Theatre Museum, Vienna', 3, false, 'object', 'https://nambatu.github.io/circart-preview/art/t4apnjmvss.jpg', 'Klimt hands the viewer a mirror and quotes Schiller above her head, telling anyone who cannot please everyone with their art to please the few instead, which is roughly the founding statement of the Vienna Secession. The painting was attacked as ugly and obscene. Klimt lived with his mother and sisters his whole life, fathered at least fourteen children by various women, and left almost no writing about his own work.', 'Q3879244', true),
('ty9mhfzgzx', '1899-winslow-homer-the-gulf-stream', 'The Gulf Stream', 'Winslow Homer', 1899, null, 'Realism', 'oil on canvas', 'Metropolitan Museum of Art, New York', 3, false, 'object', 'https://nambatu.github.io/circart-preview/art/ty9mhfzgzx.jpg', 'Buyers complained it was too bleak to hang, so Homer wrote to his dealer with heavy sarcasm, telling him to reassure the ladies that the man is rescued by the ship in the background and lives happily ever after. The Met eventually bought it. A Black sailor lies on a dismasted boat surrounded by sharks and a waterspout, painted after Homer''s trips to the Bahamas, and it is one of the most politically loaded American paintings of the century.', 'Q7738501', true),
('v9zj8dq4ps', '1904-pablo-picasso-the-old-guitarist', 'The Old Guitarist', 'Pablo Picasso', 1904, 'c. 1903-1904', 'Blue Period', 'oil on panel', 'Art Institute of Chicago', 2, false, 'object', 'https://nambatu.github.io/circart-preview/art/v9zj8dq4ps.jpg', 'X-rays and infrared reveal a woman''s face and shoulder underneath the guitarist''s neck, plus at least two other abandoned compositions, because Picasso was too poor in the Blue Period to buy fresh canvas and painted over his own work. He was 22 and living in Barcelona and Paris in genuine poverty after the suicide of his close friend Casagemas, which is the event most often credited with turning everything blue.', null, true),
('4qaunsqcfc', '1905-henri-matisse-woman-with-a-hat', 'Woman with a Hat', 'Henri Matisse', 1905, null, 'Fauvism', 'oil on canvas', 'SFMOMA, San Francisco', 2, false, 'object', 'https://nambatu.github.io/circart-preview/art/4qaunsqcfc.jpg', 'A critic walking into the room where these hung, and spotting a conventional sculpture in the middle, said it was like a Donatello among wild beasts, and Fauvism took its name from the insult. The sitter is Matisse''s wife Amélie, and the entire painting is arbitrary colour: she is green and lilac. Gertrude and Leo Stein bought it, which mattered enormously, and Matisse later said their support arrived when he was ready to give up.', 'Q1437492', true),
('n7435ev7v3', '1906-paul-cezanne-the-large-bathers', 'The Large Bathers', 'Paul Cézanne', 1906, 'c. 1900-1906', 'Post-Impressionism', 'oil on canvas', 'Philadelphia Museum of Art', 2, false, 'object', 'https://nambatu.github.io/circart-preview/art/n7435ev7v3.jpg', 'Cézanne worked on it for seven years and died before finishing it, which is roughly how he treated everything. He was terrified of the female nude and would not use live models for this, working instead from old drawings and memory, so the bodies are geometric and awkward on purpose and also possibly by accident. Picasso saw the Cézanne memorial exhibition the following year and painted Les Demoiselles d''Avignon shortly after.', null, true),
('4vjpkhaquu', '1907-gustav-klimt-portrait-of-adele-bloch-bauer-i', 'Portrait of Adele Bloch-Bauer I', 'Gustav Klimt', 1907, null, 'Art Nouveau', 'oil and gold leaf on canvas', 'Neue Galerie, New York', 1, false, 'object', 'https://nambatu.github.io/circart-preview/art/4vjpkhaquu.jpg', 'Looted from the Bloch-Bauer family by the Nazis, hung in the Belvedere as an Austrian national treasure under the fiction that Adele had bequeathed it, and only restituted in 2006 after her niece Maria Altmann fought an eight-year legal battle that reached the US Supreme Court. It then sold for $135 million, briefly a record. Klimt used gold leaf learned from his father''s engraving trade and a trip to see the Ravenna mosaics.', 'Q354396', true),
('qwmryj6exu', '1907-pablo-picasso-les-demoiselles-d-avignon', 'Les Demoiselles d''Avignon', 'Pablo Picasso', 1907, null, 'Proto-Cubism', 'oil on canvas', 'Museum of Modern Art, New York', 1, false, 'object', 'https://nambatu.github.io/circart-preview/art/qwmryj6exu.jpg', 'Picasso kept it rolled up in his studio for nine years and did not exhibit it publicly until 1916, because the reaction from the people he showed it to was so poor. Braque said it was like drinking petrol to spit fire. Matisse was reportedly furious. The two right-hand faces were repainted after Picasso saw African masks at the Trocadéro, an encounter he later described as a shock, then spent decades downplaying.', null, true),
('asybh7qdxv', '1908-gustav-klimt-the-kiss', 'The Kiss', 'Gustav Klimt', 1908, 'c. 1907-1908', 'Art Nouveau', 'oil and gold leaf on canvas', 'Belvedere, Vienna', 1, false, 'object', 'https://nambatu.github.io/circart-preview/art/asybh7qdxv.jpg', 'Klimt''s father was a gold engraver, and the gold leaf technique arrived after a trip to Ravenna to see Byzantine mosaics, which he described as astonishing. The two figures stand on a small flowered ledge with nothing beyond it, and the woman''s feet are curled over the edge. It was bought by the Austrian state before it was even finished. Klimt died of a stroke and influenza in 1918, one of a remarkable number of Viennese losses that year.', 'Q698487', true),
('2bc8t2c4jh', '1910-egon-schiele-seated-male-nude', 'Seated Male Nude', 'Egon Schiele', 1910, null, 'Expressionism', 'oil and gouache on canvas', 'Leopold Museum, Vienna', 3, true, 'object', 'https://nambatu.github.io/circart-preview/art/2bc8t2c4jh.jpg', 'Schiele was twenty and had just walked out of the Vienna Academy with a group of friends, complaining that it was strangling them. The body is cropped at the feet and hands, floating on bare paper with no ground, and rendered in colours that read as bruised. Four years later he was arrested in a small town, held for 24 days, and a judge burned one of his drawings in the courtroom with a candle flame.', null, true),
('e8kk9xsvds', '1910-henri-matisse-dance-ii', 'Dance (II)', 'Henri Matisse', 1910, null, 'Fauvism', 'oil on canvas', 'Hermitage, Saint Petersburg', 2, false, 'object', 'https://nambatu.github.io/circart-preview/art/e8kk9xsvds.jpg', 'Commissioned by the Moscow textile millionaire Sergei Shchukin for his staircase. Shchukin accepted, panicked about the nudity in front of his household, cancelled by telegram, then changed his mind again on the train home and wrote apologising. Matisse used just three colours: blue for sky, green for earth, vermilion for bodies. When it was first shown in Paris the critical reaction was so hostile that Matisse said he never read reviews again.', 'Q164517', true),
('yvudyhbnn3', '1911-franz-marc-blue-horse-i', 'Blue Horse I', 'Franz Marc', 1911, null, 'Expressionism', 'oil on canvas', 'Lenbachhaus, Munich', 2, false, 'object', 'https://nambatu.github.io/circart-preview/art/yvudyhbnn3.jpg', 'Marc worked from a private colour code he set out in a letter to August Macke: blue was masculine, austere and spiritual, yellow gentle and cheerful, red the brutal weight of matter. So a blue horse is not a stylised horse, it is a statement about what the animal is. He believed animals saw the world more purely than people did and spent years trying to paint from inside their point of view rather than looking at them. The same year he and Kandinsky founded Der Blaue Reiter, named, by Kandinsky''s account, because both of them liked horses and both of them liked blue. Marc was killed by a shell splinter at Verdun in 1916, aged 36; the German army had put him on a list of notable artists to be pulled out of combat and the order came through days too late. The Nazis later declared this decorated war casualty degenerate and stripped 130 of his works from German museums.', 'Q2592400', true),
('dkdzvarzge', '1911-georges-braque-the-portuguese', 'The Portuguese', 'Georges Braque', 1911, null, 'Analytic Cubism', 'oil on canvas', 'Kunstmuseum Basel', 3, false, 'object', 'https://nambatu.github.io/circart-preview/art/dkdzvarzge.jpg', 'Braque had trained as a house painter and decorator, which is where he learned the wood-graining, marbling and stencilled lettering he later smuggled into Cubism, and the stencilled letters and numbers here are the first printed text in a Cubist painting. He and Picasso worked so closely for several years that they compared it to being roped together on a mountain, and their canvases from this period are genuinely hard to tell apart.', 'Q60313515', true),
('x9qzfzfcgs', '1912-marcel-duchamp-nude-descending-a-staircase-no-2', 'Nude Descending a Staircase, No. 2', 'Marcel Duchamp', 1912, null, 'Cubism', 'oil on canvas', 'Philadelphia Museum of Art', 2, false, 'object', 'https://nambatu.github.io/circart-preview/art/x9qzfzfcgs.jpg', 'Rejected by the Cubists themselves, who sent Duchamp''s own brothers to ask him to change the title, and he withdrew it rather than comply. It then became the scandal of the 1913 New York Armory Show, where one critic called it an explosion in a shingle factory and it was reproduced in newspapers across America. Duchamp mostly stopped painting a few years later and played competitive chess, representing France internationally.', 'Q421716', true),
('s2r83akqae', '1913-ernst-ludwig-kirchner-street-berlin', 'Street, Berlin', 'Ernst Ludwig Kirchner', 1913, 'c. 1913-1914', 'Expressionism', 'oil on canvas', 'Museum of Modern Art, New York', 2, false, 'object', 'https://nambatu.github.io/circart-preview/art/s2r83akqae.jpg', 'The angular women are prostitutes on the Kurfürstendamm, legally tolerated and instantly identifiable to Berliners by their dress and the feathers, and the men around them are potential clients rendered as a faceless slab. Kirchner painted eleven street scenes in about eighteen months. He volunteered for the army in 1914, had a breakdown within a year, and was later declared degenerate by the Nazis, with over 600 of his works removed from German museums.', 'Q19883652', true),
('z5jdedk3rp', '1913-umberto-boccioni-unique-forms-of-continuity-in-sp', 'Unique Forms of Continuity in Space', 'Umberto Boccioni', 1913, null, 'Futurism', 'bronze', 'various collections', 2, false, 'public_sculpture', 'https://nambatu.github.io/circart-preview/art/z5jdedk3rp.jpg', 'Only cast in bronze after Boccioni died, from the original plaster, so the artist never saw the object that made him famous. He died in 1916 aged 33, not in combat but after falling from a horse during cavalry training, which for a Futurist who wrote manifestos glorifying the speed of the machine age is an ending of some irony. Italy put the sculpture on the 20-cent euro coin.', 'Q933665', true),
('spbkkhy43a', '1913-wassily-kandinsky-composition-vii', 'Composition VII', 'Wassily Kandinsky', 1913, null, 'Abstract art', 'oil on canvas', 'Tretyakov Gallery, Moscow', 2, false, 'object', 'https://nambatu.github.io/circart-preview/art/spbkkhy43a.jpg', 'Kandinsky made over thirty preparatory studies and then painted the enormous final canvas in four days with an assistant, working at speed to keep the spontaneity. He had synaesthesia and described hearing colours; he also credited a decisive moment to walking into his studio at dusk, failing to recognise one of his own paintings lying on its side, and finding it beautiful precisely because he could not read the subject.', 'Q2990634', true),
('njgjt6au5m', '1915-kazimir-malevich-black-square', 'Black Square', 'Kazimir Malevich', 1915, null, 'Suprematism', 'oil on linen', 'Tretyakov Gallery, Moscow', 1, false, 'object', 'https://nambatu.github.io/circart-preview/art/njgjt6au5m.jpg', 'Hung across the upper corner of the room at its first exhibition, the position reserved in a Russian home for the household icon, which was an unmistakable claim and everybody present understood it. Beneath the black, imaging has revealed two earlier compositions and a faint pencil inscription. The surface has cracked over a century into a network of fissures, so the painting that was meant to be pure zero is now visibly full of history.', 'Q1170315', true),
('2anet3nwtg', '1915-marc-chagall-the-birthday', 'The Birthday', 'Marc Chagall', 1915, null, 'Modernism', 'oil on cardboard', 'Museum of Modern Art, New York', 3, false, 'object', 'https://nambatu.github.io/circart-preview/art/2anet3nwtg.jpg', 'Painted a few weeks before Chagall married Bella Rosenfeld, who is the woman being kissed by a man whose neck has bent through 180 degrees to reach her. Bella wrote her own account of the day: she had brought flowers, he made her hold them and told her not to move. They were married nearly thirty years. Chagall lived to 97 and remained essentially unclassifiable within any movement.', 'Q3685142', true),
('7jydhmwhmb', '1917-amedeo-modigliani-reclining-nude', 'Reclining Nude', 'Amedeo Modigliani', 1917, null, 'Expressionism', 'oil on canvas', 'various collections', 2, true, 'object', 'https://nambatu.github.io/circart-preview/art/7jydhmwhmb.jpg', 'Police shut Modigliani''s only solo exhibition on its opening day because nudes visible through the gallery window had pubic hair, which the officer in charge apparently found decisive. Almost nothing sold. He died three years later at 35 of tubercular meningitis, having drunk and starved himself badly; his pregnant partner Jeanne Hébuterne killed herself the following day. His nudes now routinely sell for over $100 million.', 'Q19917658', true),
('4mnt7kfz8g', '1917-egon-schiele-the-embrace', 'The Embrace', 'Egon Schiele', 1917, null, 'Expressionism', 'oil on canvas', 'Belvedere, Vienna', 2, false, 'object', 'https://nambatu.github.io/circart-preview/art/4mnt7kfz8g.jpg', 'Schiele had just returned from military service, was finally selling work, and his line had loosened into something almost tender compared to his earlier drawings. The following autumn his pregnant wife Edith died of Spanish flu; he died three days later, aged 28, having spent the interval drawing her. The Vienna of 1918 lost Klimt, Schiele, Otto Wagner and Koloman Moser within months of each other.', 'Q19967004', true),
('bhv94vb4fz', '1917-marcel-duchamp-fountain', 'Fountain', 'Marcel Duchamp', 1917, null, 'Dada', 'porcelain urinal', 'lost; replicas in various collections', 1, false, 'destroyed_or_lost', 'https://nambatu.github.io/circart-preview/art/bhv94vb4fz.jpg', 'Submitted under the false name R. Mutt to an exhibition that had publicly promised to accept every submission, which was precisely the trap. The committee, which included Duchamp himself, hid it behind a partition. The original was lost almost immediately, probably thrown out as rubbish, so every Fountain in a museum today is a 1960s replica Duchamp authorised. A poll of art professionals in 2004 named it the most influential artwork of the twentieth century.', 'Q1206847', true),
('sakkk7m5dv', '1920-hannah-hoch-cut-with-the-kitchen-knife', 'Cut with the Kitchen Knife', 'Hannah Höch', 1920, null, 'Dada', 'photomontage', 'Nationalgalerie, Berlin', 3, false, 'object', 'https://nambatu.github.io/circart-preview/art/sakkk7m5dv.jpg', 'Höch cut apart Weimar magazines and pasted the Kaiser''s head onto a dancer''s body, added a map of Europe showing where women had the vote, and put her own face on it. She was the only woman in the Berlin Dada group and her male colleagues were, by her own account, condescending about it. The full title runs to sixteen words and includes the phrase Dada kitchen knife, which is the correct energy.', null, true),
('rhqx4jazmu', '1922-paul-klee-senecio', 'Senecio', 'Paul Klee', 1922, null, 'Bauhaus', 'oil on gauze', 'Kunstmuseum Basel', 2, false, 'object', 'https://nambatu.github.io/circart-preview/art/rhqx4jazmu.jpg', 'Painted while Klee was teaching at the Bauhaus in Weimar, and the title is the botanical name for ragwort, though the picture is a face built from rectangles and one raised eyebrow. Klee produced roughly 9,000 works. His teaching notes run to thousands of pages and are still in print. He was dismissed by the Nazis in 1933, fled to Switzerland, developed scleroderma and died in 1940 having made almost 1,300 works in his final year.', null, true),
('ym3rehvswa', '1923-wassily-kandinsky-composition-viii', 'Composition VIII', 'Wassily Kandinsky', 1923, null, 'Bauhaus', 'oil on canvas', 'Guggenheim Museum, New York', 3, false, 'object', 'https://nambatu.github.io/circart-preview/art/ym3rehvswa.jpg', 'After joining the Bauhaus, Kandinsky''s swirling apocalyptic storms hardened almost overnight into compasses, protractors and measured angles, and this is the pivot picture. He was teaching a course on colour theory and running questionnaires asking people which colour belonged to which shape, hoping to prove that everyone would say yellow triangle, red square, blue circle. The results were less conclusive than he wanted.', 'Q19609199', true),
('en5v4bzf8p', '1924-man-ray-le-violon-d-ingres', 'Le Violon d''Ingres', 'Man Ray', 1924, null, 'Surrealism', 'gelatin silver print', 'Getty Museum, Los Angeles', 2, true, 'object', 'https://nambatu.github.io/circart-preview/art/en5v4bzf8p.jpg', 'The f-holes were painted onto a photographic print and the whole thing rephotographed, an early piece of analogue image manipulation. The model was Kiki de Montparnasse, a singer, memoirist and painter in her own right who was far more famous in 1920s Paris than Man Ray. The French phrase means a hobby or side pursuit. The print sold in 2022 for $12.4 million, the highest price ever paid for a photograph.', null, true),
('nm929yw558', '1925-tamara-de-lempicka-self-portrait-in-the-green-bugat', 'Self-Portrait in the Green Bugatti', 'Tamara de Lempicka', 1925, 'c. 1929', 'Art Deco', 'oil on panel', 'private collection', 2, false, 'object', 'https://nambatu.github.io/circart-preview/art/nm929yw558.jpg', 'Commissioned as a cover for a German fashion magazine, and Lempicka never owned a Bugatti; she drove a small yellow Renault, which was once stolen. She built the image as pure self-promotion, the modern woman alone at the wheel in leather gloves and a helmet, and it worked. She fled Europe in 1939, had a second career slump in the 1960s, and asked for her ashes to be scattered into a Mexican volcano, which they were.', null, true),
('krk2gcpyer', '1926-constantin-brancusi-bird-in-space', 'Bird in Space', 'Constantin Brâncuși', 1926, null, 'Modern sculpture', 'polished bronze', 'various collections', 3, false, 'public_sculpture', 'https://nambatu.github.io/circart-preview/art/krk2gcpyer.jpg', 'US customs refused to classify it as art and taxed it at 40% under the tariff category for Kitchen Utensils and Hospital Supplies, arguing it did not look like a bird. Brâncuși sued. The 1928 verdict accepted that a work need not imitate nature to be art, which is one of the few times a court has meaningfully advanced modernism. He made around sixteen versions and polished the bronze ones obsessively by hand.', null, true),
('gkqg9x5rst', '1927-edward-hopper-automat', 'Automat', 'Edward Hopper', 1927, null, 'American Realism', 'oil on canvas', 'Des Moines Art Center', 2, false, 'object', 'https://nambatu.github.io/circart-preview/art/gkqg9x5rst.jpg', 'A woman sits alone at a small round table in a coin-operated cafeteria, still wearing one glove, staring into a cup. Behind her the window is pure black, and the only thing in it is the reflection of two rows of ceiling lights running back into nothing, a trick that turns the glass into a void rather than a view. Jo Hopper modelled for this figure as she did for almost every woman her husband painted, keeping the ledger of his output in her own handwriting while her own career quietly disappeared. Automats were the fast food of the 1920s, nickel-operated and open late, which is why a respectable woman could sit in one by herself at night without explanation. Hopper denied, as always, that any of it meant anything.', 'Q4808020', true),
('wt2mpa29cb', '1927-georgia-o-keeffe-oriental-poppies', 'Oriental Poppies', 'Georgia O''Keeffe', 1927, null, 'American Modernism', 'oil on canvas', 'Weisman Art Museum, Minneapolis', 2, false, 'object', 'https://nambatu.github.io/circart-preview/art/wt2mpa29cb.jpg', 'O''Keeffe spent sixty years politely and then impatiently rejecting the sexual readings critics attached to her flowers, pointing out that they were describing their own associations and then hanging them on her. She magnified the blooms because she wanted busy New Yorkers to be forced to look. She later moved permanently to New Mexico, painted bones and desert for four decades, and lived to 98.', null, true),
('srvtypj2uq', '1927-otto-dix-portrait-of-the-journalist-sylvi', 'Portrait of the Journalist Sylvia von Harden', 'Otto Dix', 1927, null, 'New Objectivity', 'mixed media on panel', 'Centre Pompidou, Paris', 2, false, 'object', 'https://nambatu.github.io/circart-preview/art/srvtypj2uq.jpg', 'Dix stopped her in the street and announced that he had to paint her because she represented an entire era, to which she reportedly replied that he presumably meant her lack of beauty. She agreed anyway. The monocle, the cigarette, the unmatched stocking and the cocktail are the visual shorthand of the Weimar New Woman. Dix was later banned from exhibiting, briefly arrested, and forced to paint inoffensive landscapes.', 'Q3399478', true),
('kwa8ybxp53', '1928-rene-magritte-the-lovers', 'The Lovers', 'René Magritte', 1928, null, 'Surrealism', 'oil on canvas', 'Museum of Modern Art, New York', 2, false, 'object', 'https://nambatu.github.io/circart-preview/art/kwa8ybxp53.jpg', 'Magritte''s mother drowned herself in the river Sambre when he was thirteen, and when the body was recovered her nightdress was reportedly wrapped around her face. Magritte disliked this explanation intensely and dismissed it whenever it was raised. He worked for years in advertising and wallpaper design, lived in a modest Brussels house, wore a bowler hat unironically, and painted in his dining room so as not to make a mess.', null, true),
('7n4cevm34h', '1929-rene-magritte-the-treachery-of-images', 'The Treachery of Images', 'René Magritte', 1929, null, 'Surrealism', 'oil on canvas', 'LACMA, Los Angeles', 1, false, 'object', 'https://nambatu.github.io/circart-preview/art/7n4cevm34h.jpg', 'Magritte''s defence was straightforward: try filling the painted pipe with tobacco. The sentence is written in the careful cursive of a school exercise book, which is part of the joke. Foucault wrote an entire book about it. Magritte later made a version showing a pipe floating above the first one and titled it in a way that ensured the second pipe was no more real than the first.', null, true),
('cym6phuq3t', '1930-elias-garcia-martinez-ecce-homo-borja', 'Ecce Homo, Borja', 'Elias Garcia Martinez', 1930, 'painted 1930; overpainted by Cecilia Gimenez in 2012, which is the version now shown', 'Academic art', 'fresco, later overpainted', 'Sanctuary of Mercy, Borja, Spain', 2, false, 'object', 'https://nambatu.github.io/circart-preview/art/cym6phuq3t.jpg', 'Elias Garcia Martinez painted a competent, forgettable Christ on a church wall in Borja in about two sittings, and it stayed unremarkable for eighty-two years. Then an elderly parishioner named Cecilia Gimenez, worried about the flaking, began restoring it herself and produced what the internet immediately christened Ecce Mono, Behold the Monkey. The original painter''s own granddaughter had donated money toward that restoration, which is the detail that makes the whole thing unbearable. What happened next is the good part: a town of a few thousand went from no visitors to tens of thousands, started charging admission, built an interpretation centre and negotiated Gimenez a share of the proceeds. There is now an opera about it. She has said she never meant to finish it that day and simply ran out of time. Note that the card shows the 2012 state of a 1930 painting, the way the Night Watch is still dated 1642 despite being cut down in 1715.', 'Q2302517', true),
('k6tt9v9yvp', '1930-grant-wood-american-gothic', 'American Gothic', 'Grant Wood', 1930, null, 'Regionalism', 'oil on beaverboard', 'Art Institute of Chicago', 1, false, 'object', 'https://nambatu.github.io/circart-preview/art/k6tt9v9yvp.jpg', 'The models were Wood''s dentist and his own sister Nan, who was so annoyed at being taken for the farmer''s wife that she spent the rest of her life correcting people, insisting she was the daughter. Iowans wrote furious letters saying it made them look grim and pinched; one farm wife threatened to bite Wood''s ear off. It won a $300 prize and has been parodied more than almost any painting alive.', 'Q464782', true),
('44fghawz8y', '1930-piet-mondrian-composition-ii-in-red-blue-and-y', 'Composition II in Red, Blue, and Yellow', 'Piet Mondrian', 1930, null, 'De Stijl', 'oil on canvas', 'Kunsthaus Zürich', 1, false, 'object', 'https://nambatu.github.io/circart-preview/art/44fghawz8y.jpg', 'Mondrian refused to use green and reportedly turned his chair away from a window in a friend''s studio because there were too many trees outside it. He arrived at pure grids after years of painting increasingly abstract trees, so the whole system grew out of the thing he later banned. He also loved dancing, was an enthusiastic Charleston devotee, and split from the De Stijl group when a colleague introduced diagonal lines.', 'Q19609193', true),
('r48mjpgg2b', '1931-salvador-dali-the-persistence-of-memory', 'The Persistence of Memory', 'Salvador Dalí', 1931, null, 'Surrealism', 'oil on canvas', 'Museum of Modern Art, New York', 1, false, 'object', 'https://nambatu.github.io/circart-preview/art/r48mjpgg2b.jpg', 'Dalí claimed the soft watches came from staring at a runny Camembert after dinner and finishing the painting in a couple of hours while Gala was at the cinema. She came back and said nobody who saw it would forget it. The fleshy shape in the centre is a distorted self-portrait profile that appears in several of his paintings. It is smaller than most people expect, about 24 by 33 centimetres.', null, true),
('dztbe4mmgb', '1932-frida-kahlo-henry-ford-hospital', 'Henry Ford Hospital', 'Frida Kahlo', 1932, null, 'Surrealism', 'oil on metal', 'Museo Dolores Olmedo, Mexico City', 3, false, 'object', 'https://nambatu.github.io/circart-preview/art/dztbe4mmgb.jpg', 'Painted in Detroit in the weeks after a miscarriage, on a sheet of metal because that was what was available and because Mexican devotional ex-votos were painted on metal too. She is on a hospital bed floating in an empty industrial landscape with the Ford plant on the horizon, connected by red ribbons to six objects including a foetus and a machine part. Kahlo was 25, and this is where her mature work begins.', 'Q118190557', true),
('kbdvkgv8ny', '1936-dorothea-lange-migrant-mother', 'Migrant Mother', 'Dorothea Lange', 1936, null, 'Documentary photography', 'gelatin silver print', 'Library of Congress, Washington', 1, false, 'object', 'https://nambatu.github.io/circart-preview/art/kbdvkgv8ny.jpg', 'Lange shot six frames in about ten minutes at a pea-pickers'' camp in California, working for a government relief agency, and the photograph prompted federal food aid to be sent within days. The woman, Florence Owens Thompson, was not identified publicly for forty years and was unhappy about it, saying she had never received anything from a picture that made everyone else money. A thumb in an early frame was retouched out.', 'Q3332083', true),
('42a8tgqmmq', '1937-pablo-picasso-guernica', 'Guernica', 'Pablo Picasso', 1937, null, 'Cubism', 'oil on canvas', 'Museo Reina Sofía, Madrid', 1, false, 'object', 'https://nambatu.github.io/circart-preview/art/42a8tgqmmq.jpg', 'Picasso refused to let it enter Spain while Franco lived, and it hung at MoMA for decades on that condition, finally arriving in Madrid in 1981. The town was bombed by German and Italian aircraft supporting Franco; Picasso, in Paris, read the newspaper reports and started within days. A tapestry copy hangs at the UN, and in 2003 it was covered with a curtain during a press conference about Iraq, which nobody has ever adequately explained.', null, true),
('ujpjjgg8b7', '1937-salvador-dali-metamorphosis-of-narcissus', 'Metamorphosis of Narcissus', 'Salvador Dalí', 1937, null, 'Surrealism', 'oil on canvas', 'Tate Modern, London', 3, false, 'object', 'https://nambatu.github.io/circart-preview/art/ujpjjgg8b7.jpg', 'Dalí took the canvas to London to show Freud in person, along with an accompanying poem. Freud, who had spent years dismissing Surrealists as cranks, wrote afterwards that he had been wrong and that this young Spaniard had changed his mind. Dalí sketched Freud during the meeting. The painting works as a single visual pun: the crouching figure on the left is also the stone hand holding an egg on the right.', null, true),
('b4aa257hjk', '1939-frida-kahlo-the-two-fridas', 'The Two Fridas', 'Frida Kahlo', 1939, null, 'Surrealism', 'oil on canvas', 'Museo de Arte Moderno, Mexico City', 1, false, 'object', 'https://nambatu.github.io/circart-preview/art/b4aa257hjk.jpg', 'Painted in the year she divorced Diego Rivera, and by a wide margin her largest canvas. Two versions of herself sit holding hands, one in European dress with a severed artery bleeding onto her lap, one in Tehuana costume holding a small portrait of Diego as a child. Kahlo had a lifelong interest in medical illustration after a streetcar accident at 18 that left her in pain permanently. She and Rivera remarried a year later.', 'Q3232010', true),
('6yp2bw8eee', '1940-frida-kahlo-self-portrait-with-thorn-necklac', 'Self-Portrait with Thorn Necklace and Hummingbird', 'Frida Kahlo', 1940, null, 'Surrealism', 'oil on canvas', 'Harry Ransom Center, Austin', 2, false, 'object', 'https://nambatu.github.io/circart-preview/art/6yp2bw8eee.jpg', 'The dead hummingbird is a Mexican folk charm for luck in love, worn here as a wound, with the thorns drawing blood at her throat. The black cat behind one shoulder and the monkey Rivera gave her behind the other pull in opposite directions. It was painted for her lover, the photographer Nickolas Muray, and he took it back to New York. Kahlo sold few paintings in her lifetime and had one solo show in Mexico, attending it in a bed.', 'Q5880026', true),
('mb57kfq4ud', '1942-edward-hopper-nighthawks', 'Nighthawks', 'Edward Hopper', 1942, null, 'American Realism', 'oil on canvas', 'Art Institute of Chicago', 1, false, 'object', 'https://nambatu.github.io/circart-preview/art/mb57kfq4ud.jpg', 'Painted in the weeks after Pearl Harbor, and Hopper said only that he was probably painting the loneliness of a large city, then spent decades refusing to elaborate on anything. There is no door into the diner. His wife Jo modelled for the woman and kept the ledger recording the painting''s details in her own handwriting. The Art Institute bought it for $3,000 within months. The diner was invented from a composite of Greenwich Avenue corners.', 'Q83872', true),
('znkdn2d4s7', '1943-norman-rockwell-freedom-from-want', 'Freedom from Want', 'Norman Rockwell', 1943, null, 'American Illustration', 'oil on canvas', 'Norman Rockwell Museum, Stockbridge', 2, false, 'object', 'https://nambatu.github.io/circart-preview/art/znkdn2d4s7.jpg', 'One of four paintings illustrating Roosevelt''s Four Freedoms speech, published in the Saturday Evening Post with accompanying essays, then sent on a national tour that raised roughly $130 million in war bonds. Rockwell used his own family and neighbours and painted the turkey from the actual Thanksgiving bird his cook prepared. Europeans complained at the time that a table groaning with food was a strange advertisement for freedom from want.', 'Q713199', true),
('mr6un9kznv', '1943-piet-mondrian-broadway-boogie-woogie', 'Broadway Boogie Woogie', 'Piet Mondrian', 1943, 'c. 1942-1943', 'De Stijl', 'oil on canvas', 'Museum of Modern Art, New York', 2, false, 'object', 'https://nambatu.github.io/circart-preview/art/mr6un9kznv.jpg', 'Mondrian fled to New York in 1940 after the London studio next to his was bombed, discovered boogie-woogie records and immediately loved them, and broke his own famous black lines into pulsing coloured segments. He was 71 and it is his last completed painting. He worked on it for months, moving small pieces of coloured tape around the canvas before committing, and visitors described the studio itself as one of his compositions.', 'Q2915406', true),
('wfdmxyk8gu', '1944-francis-bacon-three-studies-for-figures-at-the', 'Three Studies for Figures at the Base of a Crucifixion', 'Francis Bacon', 1944, null, 'Expressionism', 'oil on board', 'Tate Britain, London', 2, true, 'object', 'https://nambatu.github.io/circart-preview/art/wfdmxyk8gu.jpg', 'Shown in London in April 1945, in the same weeks the first photographs from Belsen and Buchenwald were appearing in British newspapers, and viewers reportedly left the room. Bacon later said the exhibition made his name and that he had destroyed nearly all his earlier work. The figures are based on the Furies. He painted on the unprimed reverse of the canvas, which meant the paint could never be corrected once applied.', null, true),
('njshsg2ruj', '1947-alberto-giacometti-man-pointing', 'Man Pointing', 'Alberto Giacometti', 1947, null, 'Modern sculpture', 'bronze', 'Tate Modern, London', 2, false, 'public_sculpture', 'https://nambatu.github.io/circart-preview/art/njshsg2ruj.jpg', 'Giacometti made the original plaster overnight, in a single session, because it had been promised for an exhibition the following morning, and he later said he worked on it from midnight until nine. He habitually reduced his figures until almost nothing was left, and described this as trying to sculpt what he actually saw rather than what he knew was there. His brother Diego sat for most of the figures and also made the frames.', null, true),
('m6n6jpwwm3', '1948-andrew-wyeth-christina-s-world', 'Christina''s World', 'Andrew Wyeth', 1948, null, 'Magic Realism', 'tempera on panel', 'Museum of Modern Art, New York', 1, false, 'object', 'https://nambatu.github.io/circart-preview/art/m6n6jpwwm3.jpg', 'MoMA bought it for $1,800 and critics spent the next thirty years filing Wyeth under illustration rather than art, a dismissal that only really softened after his death. Christina Olson was Wyeth''s neighbour in Maine, had an undiagnosed degenerative muscular condition and could not walk, and was 55 when he painted her; the body in the picture is his wife''s. She crawled around the property by choice, refusing a wheelchair.', 'Q2465911', true),
('gccztcnvs3', '1948-jackson-pollock-number-5-1948', 'Number 5, 1948', 'Jackson Pollock', 1948, null, 'Abstract Expressionism', 'oil on fiberboard', 'private collection', 2, false, 'object', 'https://nambatu.github.io/circart-preview/art/gccztcnvs3.jpg', 'Life magazine ran a feature in 1949 asking whether Pollock was the greatest living painter in the United States, and the question, phrased sceptically, made him famous almost overnight and he never really recovered from it. He worked on the floor with the canvas unstretched, using hardened brushes, sticks and syringes. He died in 1956 driving drunk near his home, killing one passenger. He had been sober for two years before relapsing.', 'Q1769529', true),
('6xap6n6j4e', '1948-m-c-escher-drawing-hands', 'Drawing Hands', 'M.C. Escher', 1948, null, 'Op art', 'lithograph', 'various collections', 2, false, 'object', 'https://nambatu.github.io/circart-preview/art/6xap6n6j4e.jpg', 'Escher trained as an architectural draughtsman, failed most of his school subjects and considered himself closer to a mathematician than an artist, which is roughly how the art world saw him too. He corresponded with the geometer Coxeter and the crystallographer Penrose. Mick Jagger once wrote asking to use an image on an album cover and addressed him informally; Escher declined and objected to being called Maurits by a stranger.', 'Q2390890', true),
('wb9sbec2k7', '1950-jackson-pollock-autumn-rhythm-number-30', 'Autumn Rhythm (Number 30)', 'Jackson Pollock', 1950, null, 'Abstract Expressionism', 'enamel on canvas', 'Metropolitan Museum of Art, New York', 1, false, 'object', 'https://nambatu.github.io/circart-preview/art/wb9sbec2k7.jpg', 'Hans Namuth''s photographs and films of Pollock working, made that year, did more for his reputation than any exhibition, and also made him miserable, since he felt he was performing rather than painting. The shoot ended in a furious argument after which Pollock started drinking again. The painting is nearly five metres wide, made with commercial house enamel poured and flung, and there is almost no brush contact anywhere on it.', 'Q2873092', true),
('nb57yxnawv', '1950-mark-rothko-white-center', 'White Center (Yellow, Pink and Lavender on Rose)', 'Mark Rothko', 1950, null, 'Abstract Expressionism', 'oil on canvas', 'private collection', 3, false, 'object', 'https://nambatu.github.io/circart-preview/art/nb57yxnawv.jpg', 'David Rockefeller bought this in 1960 for about $10,000 on the advice of MoMA''s curators and hung it in his office for nearly fifty years; it sold in 2007 for $72.8 million. Rothko specified that his paintings be hung low, in dim light, and viewed from around 45 centimetres away, and wrote angry letters when galleries ignored him. He rejected the label abstract painter entirely, insisting he was interested only in tragedy, ecstasy and doom, and that anyone who wept in front of the canvases was having the same experience he had while making them. The best illustration of how seriously he meant that came in 1958, when he took an enormous commission for a luxury restaurant in the Seagram Building, told a journalist he hoped to ruin the appetite of every rich diner in the room, ate there once, was disgusted and returned the money.', null, true),
('q2jjd9pacq', '1951-salvador-dali-christ-of-saint-john-of-the-cros', 'Christ of Saint John of the Cross', 'Salvador Dalí', 1951, null, 'Surrealism', 'oil on canvas', 'Kelvingrove, Glasgow', 2, false, 'object', 'https://nambatu.github.io/circart-preview/art/q2jjd9pacq.jpg', 'A visitor attacked it with a stone and tore it with his hands in 1961; it was repaired over several months. Glasgow had bought it for £8,200 amid furious local objections that the money should have gone to living Scottish artists, and it has since become the city''s most popular possession. Dalí based the viewpoint on a drawing by the sixteenth-century mystic John of the Cross, and hired a Hollywood stuntman to hang from a gantry as the model.', null, true),
('p2kwbbpnw2', '1952-willem-de-kooning-woman-i', 'Woman I', 'Willem de Kooning', 1952, 'c. 1950-1952', 'Abstract Expressionism', 'oil on canvas', 'Museum of Modern Art, New York', 2, false, 'object', 'https://nambatu.github.io/circart-preview/art/p2kwbbpnw2.jpg', 'De Kooning scraped it down and restarted for roughly two years, produced dozens of destroyed versions, and had actually thrown the canvas out before the critic Meyer Schapiro asked to see it and talked him into continuing. He said the grin came partly from a magazine advertisement for cigarettes he had pinned to the canvas. Feminist critics have attacked the series for decades; de Kooning claimed the figures made him laugh.', 'Q3569753', true),
('y7uw5sred4', '1953-francis-bacon-study-after-velazquez-s-portrait', 'Study after Velázquez''s Portrait of Pope Innocent X', 'Francis Bacon', 1953, null, 'Expressionism', 'oil on canvas', 'Des Moines Art Center', 2, false, 'object', 'https://nambatu.github.io/circart-preview/art/y7uw5sred4.jpg', 'Bacon painted around forty-five variations on the Velázquez and never once went to see the original, even when he was in Rome, which he explained by saying he did not want to spoil the reproductions he worked from. The scream is lifted partly from a still of the nurse in Eisenstein''s Battleship Potemkin and partly from a medical textbook on diseases of the mouth that he kept for its colour plates.', null, true),
('qq5p5jw4e6', '1953-m-c-escher-relativity', 'Relativity', 'M.C. Escher', 1953, null, 'Op art', 'lithograph', 'various collections', 1, false, 'object', 'https://nambatu.github.io/circart-preview/art/qq5p5jw4e6.jpg', 'Three gravitational fields coexist in one building, each with its own floor and its own inhabitants, and each staircase is being used by people from two different worlds who cannot see each other. Escher worked it out geometrically before drawing. The image has been rebuilt in Lego, recreated in Labyrinth and Inception, and used in more computer-science lectures than probably any other picture.', 'Q2635136', true),
('fhusguevcs', '1953-mark-rothko-no-61-rust-and-blue', 'No. 61 (Rust and Blue)', 'Mark Rothko', 1953, null, 'Abstract Expressionism', 'oil on canvas', 'MOCA, Los Angeles', 2, false, 'object', 'https://nambatu.github.io/circart-preview/art/fhusguevcs.jpg', 'Rothko specified that his paintings be hung low, in dim light, and viewed from about 45 centimetres away, and wrote angry letters when galleries ignored him. He rejected being called an abstract painter and insisted he was interested only in tragedy, ecstasy and doom, adding that people who wept in front of the paintings were having the same religious experience he had while painting them. He also refused to explain what any of them meant.', null, true),
('2h57p6dwww', '1955-jasper-johns-flag', 'Flag', 'Jasper Johns', 1955, '1954-55; inscribed 1954 on the reverse. Johns painted the motif for decades - this is the MoMA canvas', 'Neo-Dada', 'encaustic and collage on plywood', 'Museum of Modern Art, New York', 2, false, 'object', 'https://nambatu.github.io/circart-preview/art/2h57p6dwww.jpg', 'Johns was 24 and painted it in hot pigmented wax over strips of torn newspaper after dreaming about the flag, which means the surface is full of half-legible 1950s headlines. It is deliberately unresolvable: a painting of a flag is also a flag. He had recently destroyed almost all his earlier work. MoMA hesitated to buy it in the McCarthy era in case it was read as unpatriotic, and had a collector purchase it as a proxy.', 'Q5456612', true),
('uufmujh2hx', '1956-richard-hamilton-just-what-is-it-that-makes-today', 'Just what is it that makes today''s homes so different, so appealing?', 'Richard Hamilton', 1956, null, 'Pop art', 'collage', 'Kunsthalle Tübingen', 2, false, 'object', 'https://nambatu.github.io/circart-preview/art/uufmujh2hx.jpg', 'A small collage made as a poster and catalogue image for a London exhibition, containing the word POP on a lollipop years before Pop art existed as a term. Hamilton assembled it from American magazines in an afternoon, working from a list he had written of what should be in it: man, woman, food, newspapers, cinema, comics, cars, appliances. Britain was still under food rationing memories, and the imagery was aspirational science fiction.', 'Q3190307', true),
('3t7cgm4kug', '1959-robert-rauschenberg-monogram', 'Monogram', 'Robert Rauschenberg', 1959, 'c. 1955-1959', 'Neo-Dada', 'mixed media with taxidermied goat', 'Moderna Muséet, Stockholm', 3, false, 'public_sculpture', 'https://nambatu.github.io/circart-preview/art/3t7cgm4kug.jpg', 'Rauschenberg bought the stuffed angora goat from a second-hand office furniture shop on Seventh Avenue for $15, negotiated down from $35, and then spent four years failing to make it work in three separate versions before putting the tyre around its middle. He also repaired the goat''s face with paint. It is now the single most famous object in Sweden''s modern art museum, which bought it in 1965 for around $30,000.', 'Q6901603', true),
('85m76d4m3j', '1960-yves-klein-anthropometry-of-the-blue-period', 'Anthropometry of the Blue Period', 'Yves Klein', 1960, null, 'Nouveau Realisme', 'pigment on paper', 'Centre Pompidou, Paris', 3, false, 'performance', 'https://nambatu.github.io/circart-preview/art/85m76d4m3j.jpg', 'Performed before a black-tie audience with an orchestra playing one single sustained note for twenty minutes followed by twenty minutes of silence, while models coated in Klein''s patented blue pressed themselves onto paper at his direction. He wore a dinner jacket and never touched the paint. He patented the pigment formula as International Klein Blue. He died of a heart attack at 34, having had three in one month.', null, true),
('hvem9m5dsj', '1961-bridget-riley-movement-in-squares', 'Movement in Squares', 'Bridget Riley', 1961, null, 'Op art', 'tempera on board', 'Arts Council Collection, London', 2, false, 'object', 'https://nambatu.github.io/circart-preview/art/hvem9m5dsj.jpg', 'Riley was working as a commercial illustrator in an advertising agency when she painted this, and the compression down the centre reads as a fold in a flat surface that is not there. Op art became a fashion craze almost immediately; an American dress manufacturer copied her work onto fabric and she flew to New York to sue, discovered US copyright would not protect her, and campaigned about it for years afterwards.', 'Q119336426', true),
('cvwsh6n9sm', '1962-andy-warhol-campbell-s-soup-cans', 'Campbell''s Soup Cans', 'Andy Warhol', 1962, null, 'Pop art', 'synthetic polymer on canvas', 'Museum of Modern Art, New York', 1, false, 'object', 'https://nambatu.github.io/circart-preview/art/cvwsh6n9sm.jpg', 'Thirty-two canvases, one for every variety the company sold that year, first shown propped on a shelf running around the gallery like a supermarket aisle. A nearby dealer stacked real cans in his window with a sign offering the genuine article cheaper. Five sold, and Warhol bought them back to keep the set together. Campbell''s, after a nervous internal discussion, decided not to sue and later sent him a case of tomato soup.', 'Q2697937', true),
('sdm7bsrjy6', '1962-andy-warhol-marilyn-diptych', 'Marilyn Diptych', 'Andy Warhol', 1962, 'card image must show BOTH panels - left colour, right black and white', 'Pop art', 'silkscreen on canvas', 'Tate Modern, London', 1, false, 'object', 'https://nambatu.github.io/circart-preview/art/sdm7bsrjy6.jpg', 'Monroe died on 4 August 1962, in the same month Warhol first started experimenting with screenprinting, and over the following four months he made more than twenty paintings of her, every one built from a single cropped publicity still that Gene Kornman had shot for the 1953 film Niagara. The famous part is the left half in saturated colour against the right half fading into smeared black and white, universally read as celebrity against mortality. What is less often mentioned is that these were two separate paintings. The collectors Burton and Emily Tremaine came to the studio, were shown the black Marilyns first and the coloured one several pictures later, and Emily suggested hanging them as a diptych; Warhol''s recorded response was gee whiz yes. So the most quoted interpretation in twentieth-century American painting rests on an arrangement the buyer thought of.', 'Q573949', true),
('428zyfpvkh', '1963-roy-lichtenstein-whaam', 'Whaam!', 'Roy Lichtenstein', 1963, null, 'Pop art', 'acrylic and oil on canvas', 'Tate Modern, London', 1, false, 'object', 'https://nambatu.github.io/circart-preview/art/428zyfpvkh.jpg', 'Lifted almost directly from a 1962 DC war comic drawn by Irv Novick, who was never credited or paid, and who had reportedly been Lichtenstein''s superior officer during the war. The two-canvas format splits cause from effect. Lichtenstein enlarged the Ben-Day dots by hand using a stencil, so the mechanical look is entirely handmade. The Tate bought it in 1966, provoking complaints in Parliament about wasting public money.', 'Q3567592', true),
('2s8z535chz', '1963-roy-lichtenstein-drowning-girl', 'Drowning Girl', 'Roy Lichtenstein', 1963, null, 'Pop art', 'oil and acrylic on canvas', 'Museum of Modern Art, New York', 2, false, 'object', 'https://nambatu.github.io/circart-preview/art/2s8z535chz.jpg', 'Lichtenstein cropped a full comic panel down to a single head, deleted the boyfriend swimming toward her in the original, and rewrote the caption so she would rather drown than call him. The source was a DC romance comic. The wave is borrowed, deliberately, from Hokusai. His father-in-law reportedly asked whether he was ever going to paint anything of his own.', 'Q5308687', true),
('scu4ec2ptr', '1964-fernando-botero-pope-leo-x-after-raphael', 'Pope Leo X (after Raphael)', 'Fernando Botero', 1964, null, 'Naive art', 'oil on canvas', 'Hirshhorn Museum, Washington', 2, false, 'object', 'https://nambatu.github.io/circart-preview/art/scu4ec2ptr.jpg', 'Botero took Raphael''s 1518 portrait of Leo X, a painting the pope commissioned specifically so posterity would remember him with dignity, and turned him into something between an infant and a bureaucrat: round face, tiny features, stubby hands. Botero always insisted the inflation was about volume and sensuality rather than fat, and he had spent two years at a school for matadors before deciding on painting. Then in 2014 somebody put it on Reddit with the caption y tho, and it became the internet''s standard reaction image for anything absurd or pointless. Botero died in 2023 with the obituaries split between his monumental public sculptures and the fact that he was, technically, the creator of a meme.', null, true),
('dswvfr9nsd', '1964-norman-rockwell-the-problem-we-all-live-with', 'The Problem We All Live With', 'Norman Rockwell', 1964, null, 'American Illustration', 'oil on canvas', 'Norman Rockwell Museum, Stockbridge', 2, false, 'object', 'https://nambatu.github.io/circart-preview/art/dswvfr9nsd.jpg', 'Rockwell had just left the Saturday Evening Post after 47 years, partly because its policy forbade depicting Black people except in service roles. Freed from it at 70, he painted six-year-old Ruby Bridges walking to school past a wall smeared with a thrown tomato and a racial slur, escorted by federal marshals whose heads are cropped out of frame. Obama had it hung outside the Oval Office in 2011 and met Bridges in front of it.', 'Q6592831', true),
('cvspfbzzg9', '1964-rene-magritte-the-son-of-man', 'The Son of Man', 'René Magritte', 1964, null, 'Surrealism', 'oil on canvas', 'private collection', 1, false, 'object', 'https://nambatu.github.io/circart-preview/art/cvspfbzzg9.jpg', 'Magritte described it as a self-portrait, and said the interesting thing is that we always want to see what is hidden by what we see, that there is an interest in what is concealed and what the visible does not show us. He painted the same idea repeatedly with apples, birds and flowers over faces. It has since been used in The Thomas Crown Affair, on album covers, and in roughly every advertisement about hidden potential.', null, true),
('4jk73maxda', '1965-yayoi-kusama-infinity-mirror-room-phalli-s-fi', 'Infinity Mirror Room - Phalli''s Field', 'Yayoi Kusama', 1965, null, 'Installation art', 'mirrors and sewn fabric', 'various collections', 3, true, 'installation', 'https://nambatu.github.io/circart-preview/art/4jk73maxda.jpg', 'Kusama filled a mirrored room with hundreds of hand-sewn stuffed protrusions and photographed herself lying among them in a red leotard. She has described her work as coming directly from hallucinations she has experienced since childhood, in which patterns spread across surfaces and threaten to obliterate her. She has voluntarily lived in a Tokyo psychiatric hospital since 1977 and walks to her studio across the street to work every day.', null, true),
('pfbmvpdgd2', '1967-david-hockney-a-bigger-splash', 'A Bigger Splash', 'David Hockney', 1967, null, 'Pop art', 'acrylic on canvas', 'Tate Britain, London', 1, false, 'object', 'https://nambatu.github.io/circart-preview/art/pfbmvpdgd2.jpg', 'The splash took Hockney around two weeks to paint with small brushes, far longer than the flat blocks of building, pool and sky that surround it, which he did quickly with rollers. He liked the idea of spending that much time on something that lasts two seconds. He had moved to Los Angeles in 1964 and was struck that nobody in England had swimming pools while in California they were merely normal.', 'Q673984', true),
('f6cv64e37s', '1970-robert-smithson-spiral-jetty', 'Spiral Jetty', 'Robert Smithson', 1970, null, 'Land art', 'basalt, earth and salt', 'Great Salt Lake, Utah', 2, false, 'land_art', 'https://nambatu.github.io/circart-preview/art/f6cv64e37s.jpg', 'Smithson chose the site partly because the water there is stained red by salt-tolerant bacteria, and built the 460-metre coil from 6,000 tonnes of basalt using hired dump trucks. It vanished under rising lake water within two years and stayed submerged for three decades before reappearing in the early 2000s, encrusted in white salt. Smithson died in a plane crash in 1973 at 35 while surveying another site from the air.', 'Q668343', true),
('5jx37t2fgy', '1972-david-hockney-diving-olympics-poster', 'Diving (Olympische Spiele München 1972)', 'David Hockney', 1972, 'printed 1970-71 ahead of the Games; copyright line reads 1970 or 1971 depending on the run', 'Pop art', 'offset lithograph poster', 'V&A, London, and other collections', 2, false, 'object', 'https://nambatu.github.io/circart-preview/art/5jx37t2fgy.jpg', 'Planning for the Munich art poster series began in 1967, and the organisers deliberately went to the best artists of the day rather than to designers: the full project ran to five series of seven posters each, with Hockney''s in the third. He gave them a diver mid-entry into a pool, which is simply his California swimming-pool obsession of the late 1960s handed a public commission. Roughly half the run was printed in Germany, with his plate signature inside the image area, and half in the US with the signature below it, so the position of the signature tells you which side of the Atlantic a given copy came from. The Games themselves were meant to present a relaxed, democratic West Germany, an intention destroyed by the massacre of Israeli athletes three weeks after they opened. This copy hangs in the owner''s apartment.', null, true),
('yw7ze9jkbd', '1972-david-hockney-portrait-of-an-artist-pool-with', 'Portrait of an Artist (Pool with Two Figures)', 'David Hockney', 1972, null, 'Pop art', 'acrylic on canvas', 'private collection', 2, false, 'object', 'https://nambatu.github.io/circart-preview/art/yw7ze9jkbd.jpg', 'Hockney worked on a first version for six months and destroyed it, then finished the second in two frantic weeks before an exhibition deadline, working eighteen-hour days. The standing figure is Peter Schlesinger, his former partner, and the relationship had just ended, which the painting makes fairly obvious. It sold in 2018 for $90.3 million, then the record for a living artist, a record Hockney held until Jeff Koons took it months later.', 'Q58791744', true),
('xy3zv6xkhx', '1978-cindy-sherman-untitled-film-still-21', 'Untitled Film Still #21', 'Cindy Sherman', 1978, null, 'Postmodernism', 'gelatin silver print', 'various collections', 2, false, 'object', 'https://nambatu.github.io/circart-preview/art/xy3zv6xkhx.jpg', 'Sherman photographed herself as an imaginary career girl in a city, in a film that does not exist and never has, and the whole series works because viewers are certain they have seen the movie. She did her own hair, makeup, costumes and lighting, mostly alone with a shutter release. She made 69 of them between 1977 and 1980 and stopped when she felt the clichés had run out. MoMA bought the complete set in 1995.', 'Q80218322', true),
('xeuemqczex', '1981-jean-michel-basquiat-irony-of-a-negro-policeman', 'Irony of a Negro Policeman', 'Jean-Michel Basquiat', 1981, null, 'Neo-expressionism', 'acrylic and oilstick on wood', 'private collection', 2, false, 'object', 'https://nambatu.github.io/circart-preview/art/xeuemqczex.jpg', 'Basquiat was twenty and had been sleeping on friends'' floors two years earlier, spraying cryptic SAMO slogans around downtown Manhattan with a school friend. Within another two years he was on the cover of the New York Times Magazine. The painting''s target is the position of a Black man enforcing a system built against him, and the policeman''s hat is drawn as a cage. He died of an overdose at 27.', 'Q104862554', true),
('n267rrxquh', '1982-keith-haring-radiant-baby', 'Radiant Baby', 'Keith Haring', 1982, 'c. 1980-1982', 'Street art', 'chalk on paper', 'various collections', 2, false, 'object', 'https://nambatu.github.io/circart-preview/art/n267rrxquh.jpg', 'Haring drew these in white chalk on the black paper that covered unsold advertising panels in the New York subway, sometimes forty a day, and was arrested repeatedly for it. Commuters recognised him and stopped to talk, which he said was the point: the audience came free. He later opened a shop selling his images cheaply on purpose, infuriating the art world, and died of AIDS-related illness in 1990 at 31.', null, true),
('m7aadvvfkt', '1983-anselm-kiefer-shulamite', 'Shulamite', 'Anselm Kiefer', 1983, null, 'Neo-expressionism', 'mixed media on canvas', 'private collection', 3, false, 'object', 'https://nambatu.github.io/circart-preview/art/m7aadvvfkt.jpg', 'Kiefer took the interior of a Nazi memorial hall designed for fallen soldiers and reworked it into a scorched, blackened crypt with a small flame at the far end, retitling it after a figure in Paul Celan''s poem about the death camps. Kiefer''s early work involved photographing himself performing the Nazi salute across Europe, which was received about as badly as you would expect and was intended to be.', 'Q50315793', true),
('6zh6n7fd44', '1983-jean-michel-basquiat-hollywood-africans', 'Hollywood Africans', 'Jean-Michel Basquiat', 1983, null, 'Neo-expressionism', 'acrylic and oilstick on canvas', 'Whitney Museum, New York', 2, false, 'object', 'https://nambatu.github.io/circart-preview/art/6zh6n7fd44.jpg', 'Painted after a trip to Los Angeles with two friends, the graffiti artists Toxic and Rammellzee, whose names appear on the canvas alongside a list of the roles Black actors were offered: sugar cane, tobacco, gangsterism. The words are crossed out, a device Basquiat used constantly and explained by saying that crossing something out makes you look at it more. The yellow ground is one of his brightest.', 'Q64521508', true),
('r5nwn4ak57', '1986-jeff-koons-rabbit', 'Rabbit', 'Jeff Koons', 1986, null, 'Neo-Pop', 'stainless steel', 'various collections', 2, false, 'public_sculpture', 'https://nambatu.github.io/circart-preview/art/r5nwn4ak57.jpg', 'A cast of a cheap inflatable toy in mirror-polished stainless steel, so any photograph of it necessarily contains the photographer, and no reproduction of it can ever be neutral. It has no face. Koons had worked as a Wall Street commodities broker to fund his early production, and runs a large studio where he does not personally fabricate the objects. It sold in 2019 for $91.1 million, taking the living-artist record from Hockney.', 'Q65090699', true),
('yqbres77m8', '1988-gerhard-richter-betty', 'Betty', 'Gerhard Richter', 1988, null, 'Photorealism', 'oil on canvas', 'Saint Louis Art Museum', 2, false, 'object', 'https://nambatu.github.io/circart-preview/art/yqbres77m8.jpg', 'Painted from a photograph Richter had taken of his daughter in 1978, ten years earlier, and she is turning away from the viewer and out of the picture. In the original photograph she was looking at one of his own grey abstract paintings. Richter has moved deliberately between photorealism and pure abstraction his whole career, refusing to settle, and has said he pursues no objectives, no system and no tendency.', 'Q78640464', true),
('6zphx7n7ya', '1989-barbara-kruger-untitled-your-body-is-a-battlegr', 'Untitled (Your body is a battleground)', 'Barbara Kruger', 1989, null, 'Conceptual art', 'photographic silkscreen on vinyl', 'Broad Museum, Los Angeles', 2, false, 'object', 'https://nambatu.github.io/circart-preview/art/6zphx7n7ya.jpg', 'Made for a march on Washington in support of legal abortion, and produced as a poster before it was ever a gallery object. Kruger worked for a decade as a graphic designer at Condé Nast, and the Futura Bold Oblique in a red bar is straight out of magazine layout, which is exactly why it lands. The face is split into positive and negative halves of the same photograph.', 'Q42197075', true),
('nyzu7ja3rx', '1989-guerrilla-girls-do-women-have-to-be-naked-to-get', 'Do Women Have To Be Naked To Get Into the Met. Museum?', 'Guerrilla Girls', 1989, null, 'Feminist art', 'screenprint poster', 'various collections', 2, true, 'object', 'https://nambatu.github.io/circart-preview/art/nyzu7ja3rx.jpg', 'Designed as a New York bus advertisement, and the bus company rejected it on the grounds that the image was too suggestive, which the Guerrilla Girls immediately pointed out was the entire argument. The group formed in 1985, wear gorilla masks in public, take the names of dead women artists as pseudonyms, and count works in museums. Their recount decades later found the numbers had barely improved.', 'Q76438932', true),
('xej8f2r9ek', '1991-damien-hirst-the-physical-impossibility-of-de', 'The Physical Impossibility of Death in the Mind of Someone Living', 'Damien Hirst', 1991, null, 'Young British Artists', 'tiger shark, formaldehyde, steel', 'private collection', 1, false, 'object', 'https://nambatu.github.io/circart-preview/art/xej8f2r9ek.jpg', 'Charles Saatchi paid £50,000, most of which went on catching and shipping a four-metre tiger shark from Australia. The formaldehyde was badly injected, the shark began to rot, and the skin was eventually stretched over a fibreglass mould, prompting a genuine philosophical argument about whether it was still the same artwork. It was replaced entirely with a new shark in 2006. Hirst said the point was that you cannot really imagine your own death.', 'Q38973', true),
('pc7zgku5uw', '1993-rachel-whiteread-house', 'House', 'Rachel Whiteread', 1993, null, 'Young British Artists', 'concrete', 'destroyed 1994', 3, false, 'destroyed_or_lost', 'https://nambatu.github.io/circart-preview/art/pc7zgku5uw.jpg', 'Whiteread filled a condemned East London terraced house with concrete, then stripped away the brick shell, leaving a solid cast of the air people had lived inside. She won the Turner Prize for it and was simultaneously given a prize for worst artist by a rival group on the same evening. The local council voted to demolish it eleven weeks later, on the same day she won, and it was destroyed in January 1994.', 'Q17146854', true),
('fxukza8mf6', '1995-lucian-freud-benefits-supervisor-sleeping', 'Benefits Supervisor Sleeping', 'Lucian Freud', 1995, null, 'Figurative art', 'oil on canvas', 'private collection', 2, true, 'object', 'https://nambatu.github.io/circart-preview/art/fxukza8mf6.jpg', 'Freud worked in daily sittings over about nine months, and the sitter, Sue Tilley, was a performance artist and job centre supervisor introduced to him by a mutual friend. She has written cheerfully about the boredom and the fry-ups. Freud painted only from life, refused photographs, and was notorious for taking years over a single canvas. It sold in 2008 for $33.6 million, then a record for a living artist.', 'Q817095', true),
('cwc9bwbrwn', '1998-antony-gormley-angel-of-the-north', 'Angel of the North', 'Antony Gormley', 1998, null, 'Contemporary sculpture', 'steel', 'Gateshead, England', 2, false, 'public_sculpture', 'https://nambatu.github.io/circart-preview/art/cwc9bwbrwn.jpg', 'Locals nicknamed it the Gateshead Flasher, a formal campaign opposed its construction, and a local newspaper ran a sustained hostile front-page effort against it. It is 20 metres tall with a wingspan wider than a jumbo jet, cast partly from Gormley''s own body, and engineered to withstand winds of over 160 kph on a former colliery site. It now appears on regional tourist branding and roughly one in three people in England has seen it.', 'Q1325290', true),
('pwfbh9c9hz', '1999-andreas-gursky-99-cent', '99 Cent', 'Andreas Gursky', 1999, null, 'Contemporary photography', 'chromogenic print', 'various collections', 3, false, 'object', 'https://nambatu.github.io/circart-preview/art/pwfbh9c9hz.jpg', 'Gursky digitally flattened the perspective so that the shelves recede without ever appearing to, an effect no single lens can produce, which is why the image feels subtly wrong before you work out why. He was a student of Bernd and Hilla Becher, whose deadpan industrial typologies trained a generation of German photographers. A version sold in 2007 for $3.3 million, briefly the most expensive photograph ever sold.', 'Q112701686', true),
('y33j3qddxd', '1999-tracey-emin-my-bed', 'My Bed', 'Tracey Emin', 1999, null, 'Young British Artists', 'installation', 'Tate, London', 2, false, 'installation', 'https://nambatu.github.io/circart-preview/art/y33j3qddxd.jpg', 'Emin''s actual bed, transported with the vodka bottles, cigarette packets, underwear and used condoms that surrounded it after several days of a breakdown. Shortlisted for the Turner Prize, where two Chinese performance artists stripped to the waist and jumped on it as their own uninvited work, and a woman turned up wanting to clean it. It sold in 2014 for £2.5 million. Emin has said she came back into the room, saw it, and recognised it as finished.', 'Q6944995', true),
('8rkjg2zf4h', '2002-banksy-girl-with-balloon', 'Girl with Balloon', 'Banksy', 2002, null, 'Street art', 'stencil on wall', 'originally Waterloo Bridge, London', 1, false, 'object', 'https://nambatu.github.io/circart-preview/art/8rkjg2zf4h.jpg', 'First stencilled on a wall near Waterloo Bridge in London and painted over within a few years, like most of his early work. It was voted Britain''s favourite artwork in a 2017 poll, beating Constable and Turner, which caused a certain amount of grinding of teeth. Banksy has reused the image for charity fundraising, including a version for Syrian refugees, and it functions now more as a logo than a painting.', 'Q22000063', true),
('a6efz93mtz', '2003-olafur-eliasson-the-weather-project', 'The Weather Project', 'Olafur Eliasson', 2003, null, 'Installation art', 'mist, mirrors and monofrequency lamps', 'Tate Modern, London', 2, false, 'installation', 'https://nambatu.github.io/circart-preview/art/a6efz93mtz.jpg', 'Two million people visited Tate Modern''s Turbine Hall to lie on the floor and look at themselves in the mirrored ceiling, which was not what Eliasson had predicted they would do. The sun is a semicircle of monofrequency lamps completed by the mirror, and the mist was sugar and water. The lamps emit light at a single yellow wavelength, so everything in the hall appears in shades of yellow and black, and human faces look strange.', 'Q22672619', true),
('awwyrhgtu6', '2007-damien-hirst-for-the-love-of-god', 'For the Love of God', 'Damien Hirst', 2007, null, 'Young British Artists', 'platinum, diamonds, human teeth', 'private collection', 2, false, 'object', 'https://nambatu.github.io/circart-preview/art/awwyrhgtu6.jpg', 'A platinum cast of an eighteenth-century human skull set with 8,601 diamonds, with the original teeth put back into the jaw, and it cost around £14 million to make. The title comes from Hirst''s mother, who reportedly asked what on earth he was going to do next. It was announced as sold for £50 million to an investment group that turned out to include Hirst himself, which prompted a certain amount of comment.', 'Q6400207', true),
('m2x9ftqugj', '2010-ai-weiwei-sunflower-seeds', 'Sunflower Seeds', 'Ai Weiwei', 2010, null, 'Installation art', 'porcelain', 'Tate Modern, London', 2, false, 'installation', 'https://nambatu.github.io/circart-preview/art/m2x9ftqugj.jpg', 'One hundred million porcelain seeds, each individually hand-painted by around 1,600 workers in Jingdezhen, a town that produced imperial porcelain for centuries and had been in economic decline. Visitors were initially allowed to walk on them until dust concerns closed the surface off. Sunflower seeds are a common Chinese snack and also propaganda imagery, with Mao as the sun and the people as seeds turning toward him.', 'Q10683893', true),
('9mdbnvqxnh', '2010-barbara-kruger-you-re-right-and-you-know-it-and', 'You''re Right and You Know It (And So Should Everyone Else)', 'Barbara Kruger', 2010, null, 'Conceptual art', 'offset lithograph, edition of 200', 'private collections', 2, false, 'object', 'https://nambatu.github.io/circart-preview/art/9mdbnvqxnh.jpg', 'A long, narrow strip nine inches high and twenty-four wide, published for the Editions and Artists Books Fair in New York in an edition of 200, each signed and numbered on the back. The image is a woman with an expression of open fear, and the text laid across it is completely certain of itself, which is the mechanism: Kruger spent over a decade as a designer and picture editor at Conde Nast, and she builds these the way a magazine builds a cover line, so the confidence reads as borrowed rather than earned. Her signature white Futura Bold Oblique on a red bar dates from 1981, and in 1994 Supreme''s founder handed a designer a book of her work; the resulting box logo is the same typeface on the same red rectangle, and he later conceded in court filings that it came directly from her. She has never sued, telling the New Yorker in 2017 that she owns neither the typeface nor a logo. Then in 2013 Supreme sued a small womenswear label for $10 million over Supreme Bitch merchandise, and Complex asked Kruger for comment. She replied with a blank email and one attached Word document, named fools.doc, containing the line "What a ridiculous clusterfuck of totally uncool jokers" and a note that she was waiting for all of them to sue her for infringement. Bootleg hats and stickers bearing the acronym appeared within days. She later staged a pop-up shop titled Untitled (The Drop), parodying the weekly release model Supreme built its business on. This copy hangs in the owner''s apartment.', 'Q102977536', true),
('mhw7zzkreg', '2010-marina-abramovic-the-artist-is-present', 'The Artist Is Present', 'Marina Abramović', 2010, null, 'Performance art', 'performance', 'Museum of Modern Art, New York', 2, false, 'performance', 'https://nambatu.github.io/circart-preview/art/mhw7zzkreg.jpg', 'Abramović sat silently at a table in MoMA for 736 hours over three months, opposite whoever chose to sit down, and more than 1,500 people did, some queuing overnight. Many cried. On the opening day her former partner Ulay, with whom she had ended a twelve-year relationship in 1988 by walking toward each other from opposite ends of the Great Wall of China, sat down unannounced, and she broke the rules to take his hands.', null, true),
('bxew87tbh9', '2013-kc-green-this-is-fine', 'This Is Fine', 'KC Green', 2013, null, 'Webcomic', 'digital comic', 'published online in the strip Gunshow', 2, false, 'object', 'https://nambatu.github.io/circart-preview/art/bxew87tbh9.jpg', 'Two panels from a six-panel strip: a dog in a hat sits in a burning room with a coffee cup and says everything is fine. What the meme cuts off is the rest of the strip, in which the dog''s face melts and it dies. Green has been openly uneasy about the crop, partly because the ending is the point and partly because the image gets used by exactly the institutions it satirises, including a US political party account during the 2016 election, which prompted him to say publicly that they should stop. He later drew a sequel in which the dog gets up and puts the fire out. Nobody shares that one.', null, true),
('3cu6msbkx9', '2014-kerry-james-marshall-untitled-studio', 'Untitled (Studio)', 'Kerry James Marshall', 2014, null, 'Contemporary painting', 'acrylic on PVC', 'Metropolitan Museum of Art, New York', 3, false, 'object', 'https://nambatu.github.io/circart-preview/art/3cu6msbkx9.jpg', 'Marshall paints his figures in an unmixed, near-absolute black, arguing that the Western canon simply has no vocabulary for Black skin and that he intends to supply one rather than negotiate with the existing palette. The painting shows a photographer''s studio, a space where images of Black people are deliberately constructed. He has spent his career filling what he calls a vacuum in the museum, and the Met bought this one directly.', 'Q96399238', true),
('jwkhx4xhbj', '2018-banksy-love-is-in-the-bin', 'Love Is in the Bin', 'Banksy', 2018, null, 'Street art', 'spray paint and acrylic on canvas', 'Staatsgalerie Stuttgart', 2, false, 'object', 'https://nambatu.github.io/circart-preview/art/jwkhx4xhbj.jpg', 'The canvas shredded itself seconds after the hammer fell at Sotheby''s on a £1.04 million sale, via a mechanism Banksy had built into the frame years earlier. It was supposed to shred completely and jammed halfway, which he later admitted in a video. The buyer went through with the purchase, the work was renamed, and it resold in 2021 for £18.6 million, roughly eighteen times the price it destroyed itself over.', 'Q56886750', true),
('fq79un2nqa', '2019-maurizio-cattelan-comedian', 'Comedian', 'Maurizio Cattelan', 2019, null, 'Conceptual art', 'banana, duct tape and certificate of authenticity', 'private collections', 2, false, 'installation', 'https://nambatu.github.io/circart-preview/art/fq79un2nqa.jpg', 'A banana taped to a wall at an art fair in Miami, in an edition of three, two of which sold at $120,000 each. What the buyer receives is a certificate and a set of instructions specifying the tape angle and the replacement interval, because the banana is a consumable. Within days a performance artist pulled it off the wall and ate it in front of the crowd, and the gallery simply taped up another one from a fruit stand down the road, which proved the point better than the work had. Cattelan had spent weeks trying to sculpt a banana in resin and bronze before concluding that an actual banana was funnier. A later edition sold at auction for several million to a cryptocurrency executive, who also ate it.', 'Q77715187', true),
('ccwaepc5bv', '2024-marina-caspe-untitled-collage', 'Untitled (Collage)', 'Marina Caspe', 2024, null, 'Contemporary', 'magazine and mixed media on canvas', 'Caspe family estate', 3, false, 'object', 'https://nambatu.github.io/circart-preview/art/ccwaepc5bv.jpg', 'Caspe was born on Nantucket in 2001, took a BA at Roger Williams University and then a ceramics MA at the Royal College of Art, finishing in 2024, and this collage comes out of that London year rather than from the surreal coil-built figures she is better known for. She has said that growing up on an island is what made her curious about everywhere else, and the travel since has fed the textures and the stories in the sculptures. She also runs a non-profit, The Bowl That Keeps on Giving, which sells art to fund food for malnourished children, and presented it at an international arts conference in Poland in 2023, which is a more useful thing to have done at 22 than most graduate shows manage. She later made three small ceramic books holding excerpts from her collages; one of them is in the owner''s collection.', null, true)
